# Preview deployments are isolated test environments. Keep a permanent visual
# marker on every HTML page so testers cannot mistake staging for production.
IS_STAGING_ENV = os.environ.get("VERCEL_ENV", "").strip().lower() == "preview"


@app.after_request
def add_staging_environment_badge(response):
    if not IS_STAGING_ENV or response.mimetype != "text/html":
        return response
    try:
        html = response.get_data(as_text=True)
    except (RuntimeError, UnicodeDecodeError):
        return response
    if "</body>" not in html:
        return response
    badge = (
        '<div aria-label="Staging test environment" '
        'style="position:fixed;left:14px;bottom:14px;z-index:99999;'
        'padding:9px 13px;border-radius:999px;background:#FFF3CD;'
        'border:1px solid #E5B94E;color:#5C4300;font-family:Montserrat,'
        'Arial,sans-serif;font-size:12px;font-weight:800;letter-spacing:.04em;'
        'box-shadow:0 6px 20px rgba(0,0,0,.16);">'
        'STAGING · TEST ENVIRONMENT · NOT LIVE</div>'
    )
    response.set_data(html.replace("</body>", badge + "</body>", 1))
    return response

