def ensure_daily_home_content_schema():
    """Store reusable joke/word banks plus stable per-day assignments."""
    with db_connect() as connection:
        connection.execute("""
            CREATE TABLE IF NOT EXISTS daily_home_jokes (
                id TEXT PRIMARY KEY,
                joke_text TEXT NOT NULL,
                active INTEGER NOT NULL DEFAULT 1,
                created_at TEXT NOT NULL
            )
        """)
        connection.execute("""
            CREATE TABLE IF NOT EXISTS daily_home_words (
                id TEXT PRIMARY KEY,
                word TEXT NOT NULL,
                definition TEXT NOT NULL,
                example TEXT DEFAULT '',
                active INTEGER NOT NULL DEFAULT 1,
                created_at TEXT NOT NULL
            )
        """)
        connection.execute("""
            CREATE TABLE IF NOT EXISTS daily_home_assignments (
                day_key TEXT PRIMARY KEY,
                joke_id TEXT,
                word_id TEXT,
                created_at TEXT NOT NULL
            )
        """)
        connection.commit()


def _daily_home_pick(table, day_key, salt):
    with db_connect() as connection:
        # The caller reads the selected item by column name (e.g. row['id']).
        # Request Row/HybridRow results on both SQLite and Postgres; otherwise
        # this helper returns tuples and the homepage silently drops the daily
        # content in inject_daily_home_content().
        connection.row_factory = sqlite3.Row
        rows = connection.execute(
            f"SELECT * FROM {table} WHERE COALESCE(active,1)=1 ORDER BY created_at,id"
        ).fetchall()
    if not rows:
        return None
    ordinal = date.fromisoformat(day_key).toordinal()
    offset = sum(ord(ch) for ch in str(salt))
    return rows[(ordinal + offset) % len(rows)]


def _daily_home_content():
    day_key = nz_today().isoformat()
    with db_connect() as connection:
        connection.row_factory = sqlite3.Row
        assigned = connection.execute(
            "SELECT * FROM daily_home_assignments WHERE day_key=?", (day_key,)
        ).fetchone()
        joke = None
        word = None
        if assigned and assigned['joke_id']:
            joke = connection.execute(
                "SELECT * FROM daily_home_jokes WHERE id=? AND COALESCE(active,1)=1",
                (assigned['joke_id'],),
            ).fetchone()
        if assigned and assigned['word_id']:
            word = connection.execute(
                "SELECT * FROM daily_home_words WHERE id=? AND COALESCE(active,1)=1",
                (assigned['word_id'],),
            ).fetchone()

    # Pick missing assignments deterministically, then persist them so today's
    # content does not change if an admin uploads more items during the day.
    if joke is None:
        joke = _daily_home_pick('daily_home_jokes', day_key, 'joke')
    if word is None:
        word = _daily_home_pick('daily_home_words', day_key, 'word')
    joke_id = joke['id'] if joke is not None else None
    word_id = word['id'] if word is not None else None
    if joke_id or word_id:
        with db_connect() as connection:
            existing = connection.execute(
                "SELECT day_key FROM daily_home_assignments WHERE day_key=?", (day_key,)
            ).fetchone()
            if existing:
                connection.execute(
                    "UPDATE daily_home_assignments SET joke_id=COALESCE(joke_id,?), word_id=COALESCE(word_id,?) WHERE day_key=?",
                    (joke_id, word_id, day_key),
                )
            else:
                connection.execute(
                    "INSERT INTO daily_home_assignments(day_key,joke_id,word_id,created_at) VALUES (?,?,?,?)",
                    (day_key, joke_id, word_id, nz_now_iso()),
                )
            connection.commit()

    return {
        'joke': dict(joke) if joke is not None else None,
        'word': dict(word) if word is not None else None,
    }


@app.context_processor
def inject_daily_home_content():
    try:
        content = _daily_home_content()
    except Exception:
        content = {'joke': None, 'word': None}
    return {
        'home_daily_joke': content.get('joke'),
        'home_daily_word': content.get('word'),
    }


def _parse_daily_content_upload(file_storage, kind):
    if not file_storage or not file_storage.filename:
        raise ValueError('Choose a file to upload.')
    filename = file_storage.filename.lower()
    raw = file_storage.read()
    items = []
    if filename.endswith(('.xlsx', '.xls')):
        frame = pd.read_excel(BytesIO(raw)).fillna('')
        columns = {str(c).strip().casefold(): c for c in frame.columns}
        if kind == 'jokes':
            col = columns.get('joke') or columns.get('joke_text') or (frame.columns[0] if len(frame.columns) else None)
            if col is None:
                raise ValueError('The spreadsheet needs a joke column.')
            items = [{'joke_text': str(v).strip()} for v in frame[col].tolist() if str(v).strip()]
        else:
            word_col = columns.get('word') or (frame.columns[0] if len(frame.columns) else None)
            def_col = columns.get('definition') or (frame.columns[1] if len(frame.columns) > 1 else None)
            ex_col = columns.get('example')
            if word_col is None or def_col is None:
                raise ValueError('The spreadsheet needs word and definition columns.')
            for _, row in frame.iterrows():
                word = str(row[word_col]).strip(); definition = str(row[def_col]).strip()
                if word and definition:
                    items.append({'word': word, 'definition': definition, 'example': str(row[ex_col]).strip() if ex_col else ''})
        return items

    text = raw.decode('utf-8-sig', errors='replace')
    if filename.endswith('.csv'):
        rows = list(csv.DictReader(StringIO(text)))
        if not rows:
            return []
        if kind == 'jokes':
            for row in rows:
                value = row.get('joke') or row.get('joke_text') or next(iter(row.values()), '')
                if str(value or '').strip():
                    items.append({'joke_text': str(value).strip()})
        else:
            for row in rows:
                word = str(row.get('word') or '').strip()
                definition = str(row.get('definition') or '').strip()
                if word and definition:
                    items.append({'word': word, 'definition': definition, 'example': str(row.get('example') or '').strip()})
        return items

    # TXT fallback: one joke per non-empty line, or word | definition | example.
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        if kind == 'jokes':
            items.append({'joke_text': line})
        else:
            parts = [part.strip() for part in line.split('|')]
            if len(parts) >= 2 and parts[0] and parts[1]:
                items.append({'word': parts[0], 'definition': parts[1], 'example': parts[2] if len(parts) > 2 else ''})
    return items


def _territory_user_id():
    """Return the signed-in user's territory scope for personal Sales views."""
    user = getattr(g, "current_user", None) or {}
    return int(user["id"]) if user.get("role") in {"sales_rep", "manager", "sales_manager"} and user.get("id") else None


def _visible_customer_names():
    user_id = _territory_user_id()
    if user_id is None:
        return None
    with db_connect() as connection:
        rows = connection.execute(
            "SELECT name FROM route_customers WHERE assigned_user_id=? OR assigned_user_id IS NULL",
            (user_id,),
        ).fetchall()
    return {str(row[0]).strip().casefold() for row in rows if row[0]}


def _customer_visible_to_current_user(store_name):
    visible = _visible_customer_names()
    return visible is None or str(store_name or "").strip().casefold() in visible


def _filter_customer_rows(rows, name_key="store_name"):
    visible = _visible_customer_names()
    if visible is None:
        return rows
    return [row for row in rows if str(row.get(name_key, "")).strip().casefold() in visible]


