def ensure_performance_owner_schema():
    """Add per-rep ownership to saved performance data while preserving all existing rows."""
    with db_connect() as connection:
        for table in ("monthly_sales", "opportunity_analyses", "rep_bonus_transactions"):
            columns = {row[1] for row in connection.execute(f"PRAGMA table_info({table})").fetchall()}
            if "owner_user_id" not in columns:
                connection.execute(f"ALTER TABLE {table} ADD COLUMN owner_user_id INTEGER")
        connection.commit()

        if USE_POSTGRES:
            # The original desktop schema used global uniqueness. In the multi-user cloud
            # version, owned rows must be unique inside a rep account, not across all reps.
            for statement in (
                "ALTER TABLE opportunity_analyses DROP CONSTRAINT IF EXISTS opportunity_analyses_store_name_key",
                "ALTER TABLE monthly_sales DROP CONSTRAINT IF EXISTS monthly_sales_salesperson_year_month_key",
                "ALTER TABLE rep_bonus_transactions DROP CONSTRAINT IF EXISTS rep_bonus_transactions_salesperson_doc_number_key",
                "CREATE UNIQUE INDEX IF NOT EXISTS opportunity_analyses_owner_store_uq ON opportunity_analyses (owner_user_id, lower(trim(store_name))) WHERE owner_user_id IS NOT NULL",
                "CREATE UNIQUE INDEX IF NOT EXISTS opportunity_analyses_legacy_store_uq ON opportunity_analyses (lower(trim(store_name))) WHERE owner_user_id IS NULL",
                "CREATE UNIQUE INDEX IF NOT EXISTS monthly_sales_owner_period_uq ON monthly_sales (owner_user_id, year, month) WHERE owner_user_id IS NOT NULL",
                "CREATE UNIQUE INDEX IF NOT EXISTS monthly_sales_legacy_period_uq ON monthly_sales (lower(trim(salesperson)), year, month) WHERE owner_user_id IS NULL",
                "CREATE UNIQUE INDEX IF NOT EXISTS rep_bonus_owner_doc_uq ON rep_bonus_transactions (owner_user_id, doc_number) WHERE owner_user_id IS NOT NULL",
                "CREATE UNIQUE INDEX IF NOT EXISTS rep_bonus_legacy_doc_uq ON rep_bonus_transactions (lower(trim(salesperson)), doc_number) WHERE owner_user_id IS NULL",
            ):
                connection.execute(statement)
            connection.commit()


def _private_workspace_user_id():
    """Sales Reps and Sales Managers own their personal Actions and Checklist records; Admin keeps the broader view."""
    user = getattr(g, "current_user", None) or {}
    return int(user["id"]) if user.get("role") in {"sales_rep", "manager", "sales_manager"} and user.get("id") else None


def _action_owned_by_current_user(record):
    owner_user_id = _private_workspace_user_id()
    if owner_user_id is None:
        return True
    try:
        value = record["owner_user_id"]
    except Exception:
        value = None
    # Legacy actions can legitimately have no owner. Allow the visible rep to
    # claim/reassign those records; customer visibility is still enforced by
    # the action routes. Actions already owned by another rep remain private.
    if value is None:
        return True
    try:
        return int(value) == owner_user_id
    except (TypeError, ValueError):
        return False


def ensure_private_workspace_schema():
    """Add private rep ownership for Actions and a separate personal weekly checklist."""
    with db_connect() as connection:
        action_columns = {row[1] for row in connection.execute("PRAGMA table_info(store_actions)").fetchall()}
        if "owner_user_id" not in action_columns:
            connection.execute("ALTER TABLE store_actions ADD COLUMN owner_user_id INTEGER")

        # Preserve visibility of legacy production actions. Older Sales Assistant
        # records may pre-date per-user ownership, so attach them to the rep who
        # currently owns the matching customer. This is additive only: existing
        # owner_user_id values are never changed.
        connection.execute(
            """
            UPDATE store_actions
            SET owner_user_id = (
                SELECT rc.assigned_user_id
                FROM route_customers rc
                WHERE rc.assigned_user_id IS NOT NULL
                  AND lower(trim(rc.name)) = lower(trim(store_actions.store_name))
                LIMIT 1
            )
            WHERE owner_user_id IS NULL
              AND EXISTS (
                SELECT 1
                FROM route_customers rc
                WHERE rc.assigned_user_id IS NOT NULL
                  AND lower(trim(rc.name)) = lower(trim(store_actions.store_name))
              )
            """
        )
        connection.execute(
            """
            CREATE TABLE IF NOT EXISTS user_weekly_checklist (
                owner_user_id INTEGER NOT NULL,
                week_key TEXT NOT NULL,
                item_key TEXT NOT NULL,
                is_done INTEGER NOT NULL DEFAULT 0,
                updated_at TEXT NOT NULL,
                PRIMARY KEY (owner_user_id, week_key, item_key)
            )
            """
        )
        connection.commit()




def ensure_next_visit_requirement_schema():
    """Store one lightweight active planning cue per customer/user without creating notification noise."""
    with db_connect() as connection:
        connection.execute(
            """CREATE TABLE IF NOT EXISTS next_visit_requirements (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_id INTEGER,
                store_name TEXT NOT NULL,
                owner_user_id INTEGER NOT NULL,
                requirement_text TEXT NOT NULL,
                notice_days INTEGER NOT NULL DEFAULT 0,
                status TEXT NOT NULL DEFAULT 'Active',
                source_visit_date TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                resolved_at TEXT NOT NULL DEFAULT ''
            )"""
        )
        connection.commit()


def _active_next_visit_requirement(connection, customer_id=None, store_name='', owner_user_id=None):
    """Return the signed-in user's current planning cue for a customer."""
    owner_user_id = int(owner_user_id or (getattr(g, 'current_user', None) or {}).get('id') or 0)
    if not owner_user_id:
        return None

    columns = (
        'id', 'customer_id', 'store_name', 'owner_user_id', 'requirement_text',
        'notice_days', 'status', 'source_visit_date', 'created_at', 'updated_at', 'resolved_at',
    )

    def as_requirement_dict(row):
        if not row:
            return None
        if hasattr(row, 'keys'):
            return {key: row[key] for key in row.keys()}
        return dict(zip(columns, row))

    select_columns = ','.join(columns)
    if customer_id:
        row = connection.execute(
            f"SELECT {select_columns} FROM next_visit_requirements WHERE owner_user_id=? AND status='Active' AND customer_id=? ORDER BY updated_at DESC,id DESC LIMIT 1",
            (owner_user_id, int(customer_id)),
        ).fetchone()
        requirement = as_requirement_dict(row)
        if requirement:
            return requirement
    if store_name:
        row = connection.execute(
            f"SELECT {select_columns} FROM next_visit_requirements WHERE owner_user_id=? AND status='Active' AND lower(trim(store_name))=lower(trim(?)) ORDER BY updated_at DESC,id DESC LIMIT 1",
            (owner_user_id, store_name),
        ).fetchone()
        requirement = as_requirement_dict(row)
        if requirement:
            return requirement
    return None


