def ensure_customer_identity_schema():
    """Ensure durable customer-ID links without repeating the expensive legacy migration.

    Normal cold starts only verify the required customer_id columns/indexes. The
    legacy name-to-ID backfill and snapshot synchronisation run once, then are
    marked complete in app_state. Ongoing customer edits synchronise only the
    customer being changed via _sync_customer_name_snapshots().
    """
    linked_tables = {
        "customer_priorities": "store_name",
        "store_actions": "store_name",
        "opportunity_analyses": "store_name",
        "customer_contacts": "store_name",
        "road_visit_notes": "store_name",
        "road_visit_attachments": "store_name",
        "appointment_objectives": "store_name",
        "historical_customer_calls": "store_name",
        "next_visit_requirements": "store_name",
        "trip_appointments": "store_name",
        "quality_cases": "customer_name",
    }
    migration_key = "customer_identity_backfill_v1"
    with db_connect() as connection:
        connection.row_factory = sqlite3.Row
        connection.execute(
            """CREATE TABLE IF NOT EXISTS app_state (
                state_key TEXT PRIMARY KEY,
                state_value TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL
            )"""
        )

        # Cheap, idempotent schema checks remain safe on every cold start.
        table_columns = {}
        for table in linked_tables:
            columns = {row[1] for row in connection.execute(f"PRAGMA table_info({table})").fetchall()}
            table_columns[table] = columns
            if not columns:
                continue
            if "customer_id" not in columns:
                connection.execute(f"ALTER TABLE {table} ADD COLUMN customer_id INTEGER")
                columns.add("customer_id")
            connection.execute(f"CREATE INDEX IF NOT EXISTS idx_{table}_customer_id ON {table}(customer_id)")
        connection.commit()

        migrated = connection.execute(
            "SELECT state_value FROM app_state WHERE state_key=?",
            (migration_key,),
        ).fetchone()
        if migrated and str(migrated[0] or '').strip() == 'complete':
            return

        # One-time legacy migration: attach unresolved name-based rows to the
        # permanent route_customers.id, then align compatibility name snapshots.
        customers = [dict(row) for row in connection.execute(
            "SELECT id,name,external_id,portatour_id FROM route_customers WHERE name IS NOT NULL AND trim(name)!=''"
        ).fetchall()]
        by_name = {_customer_match_key(row['name']): int(row['id']) for row in customers if row.get('name')}

        for table, name_column in linked_tables.items():
            columns = table_columns.get(table) or set()
            if not columns or "customer_id" not in columns or name_column not in columns:
                continue
            rows = connection.execute(
                f"SELECT * FROM {table} WHERE customer_id IS NULL AND {name_column} IS NOT NULL AND trim({name_column})!=''"
            ).fetchall()
            pk_columns = [
                row[1]
                for row in connection.execute(f"PRAGMA table_info({table})").fetchall()
                if int(row[5] or 0) > 0
            ]
            for row in rows:
                cid = by_name.get(_customer_match_key(row[name_column]))
                if not cid:
                    continue
                if pk_columns:
                    where = " AND ".join(f"{col}=?" for col in pk_columns)
                    params = [cid] + [row[col] for col in pk_columns]
                    connection.execute(f"UPDATE {table} SET customer_id=? WHERE {where}", params)
                elif 'id' in columns:
                    connection.execute(f"UPDATE {table} SET customer_id=? WHERE id=?", (cid, row['id']))

        for customer in customers:
            _sync_customer_name_snapshots(connection, int(customer['id']), customer['name'])

        now = datetime.now().isoformat(timespec='seconds')
        connection.execute(
            "INSERT INTO app_state (state_key,state_value,updated_at) VALUES (?,?,?) "
            "ON CONFLICT(state_key) DO UPDATE SET state_value=excluded.state_value,updated_at=excluded.updated_at",
            (migration_key, 'complete', now),
        )
        connection.commit()

def _sync_customer_name_snapshots(connection, customer_id, canonical_name=None):
    """Synchronise denormalised customer-name snapshots for one durable customer ID."""
    if not customer_id:
        return
    if canonical_name is None:
        row = connection.execute("SELECT name FROM route_customers WHERE id=?", (int(customer_id),)).fetchone()
        canonical_name = row[0] if row else ''
    canonical_name = str(canonical_name or '').strip()
    if not canonical_name:
        return
    table_columns = {
        "customer_priorities": "store_name",
        "store_actions": "store_name",
        "opportunity_analyses": "store_name",
        "customer_contacts": "store_name",
        "road_visit_notes": "store_name",
        "road_visit_attachments": "store_name",
        "appointment_objectives": "store_name",
        "historical_customer_calls": "store_name",
        "next_visit_requirements": "store_name",
        "trip_appointments": "store_name",
        "quality_cases": "customer_name",
    }
    for table, name_column in table_columns.items():
        columns = {row[1] for row in connection.execute(f"PRAGMA table_info({table})").fetchall()}
        if "customer_id" in columns and name_column in columns:
            connection.execute(
                f"UPDATE {table} SET {name_column}=? WHERE customer_id=?",
                (canonical_name, int(customer_id)),
            )

def _resolve_customer_id(connection, store_name):
    key = _customer_match_key(store_name)
    if not key:
        return None
    rows = connection.execute("SELECT id,name FROM route_customers WHERE name IS NOT NULL").fetchall()
    for row in rows:
        if _customer_match_key(row[1]) == key:
            return int(row[0])
    return None


def _customer_link_clause(customer_id, store_name, column_prefix=""):
    prefix = f"{column_prefix}." if column_prefix else ""
    if customer_id:
        return f"({prefix}customer_id=? OR ({prefix}customer_id IS NULL AND lower(trim({prefix}store_name))=lower(trim(?))))", [customer_id, store_name]
    return f"lower(trim({prefix}store_name))=lower(trim(?))", [store_name]


def _trip_owner_user_id():
    """Return the personal trip owner for Sales Rep and Sales Manager Sales views."""
    user = getattr(g, "current_user", None) or {}
    return int(user["id"]) if user.get("role") in {"sales_rep", "manager", "sales_manager"} and user.get("id") else None


def _trip_row_for_current_user(connection, trip_id):
    owner_user_id = _trip_owner_user_id()
    if owner_user_id is None:
        return connection.execute("SELECT * FROM trip_plans WHERE id=?", (trip_id,)).fetchone()
    return connection.execute("SELECT * FROM trip_plans WHERE id=? AND owner_user_id=?", (trip_id, owner_user_id)).fetchone()


def _trip_accessible(trip_id):
    if not trip_id:
        return False
    with db_connect() as connection:
        return _trip_row_for_current_user(connection, trip_id) is not None


def _current_user_state_key(base_key):
    user = getattr(g, "current_user", None) or {}
    user_id = user.get("id")
    return f"{base_key}:user:{user_id}" if user_id else base_key








def audit_event(event_type, detail="", trip_id=None, appointment_id=""):
    """Record a lightweight business audit event, including the signed-in actor when available."""
    try:
        actor = getattr(g, "current_user", None) or {}
        actor_user_id = actor.get("id")
        actor_email = str(actor.get("email") or "")
        with db_connect() as connection:
            connection.execute(
                "INSERT INTO audit_log (event_type,detail,trip_id,appointment_id,actor_user_id,actor_email,created_at) VALUES (?,?,?,?,?,?,?)",
                (event_type, str(detail or ""), trip_id, appointment_id or "", actor_user_id, actor_email, datetime.now().isoformat(timespec="seconds")),
            )
            connection.commit()
    except Exception:
        pass

def create_database_backup(reason="manual"):
    # Neon handles durable database storage/backups in cloud mode. This legacy
    # local-file backup is retained only for the SQLite desktop version.
    if USE_POSTGRES:
        return None
    if not DATABASE_PATH.exists():
        return None
    stamp=datetime.now().strftime("%Y%m%d-%H%M%S")
    target=BACKUP_DIR / f"sales_history-{stamp}-{re.sub(r'[^A-Za-z0-9_-]+','_',reason)[:30]}.db"
    with sqlite3.connect(DATABASE_PATH) as source, sqlite3.connect(target) as dest:
        source.backup(dest)
    return target

def appointment_uid(trip_id, schedule_id, visit_date, visit_time, store_name):
    raw=f"{trip_id or 0}|{schedule_id or 0}|{visit_date}|{visit_time}|{str(store_name).strip().casefold()}"
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()

def ensure_reliability_tables(connection):
    """Create Stage 9 support tables and columns before any reliability feature uses them."""
    connection.execute(
        """CREATE TABLE IF NOT EXISTS app_state (
            state_key TEXT PRIMARY KEY,
            state_value TEXT NOT NULL DEFAULT '',
            updated_at TEXT NOT NULL
        )"""
    )
    connection.execute(
        """CREATE TABLE IF NOT EXISTS audit_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_type TEXT NOT NULL,
            detail TEXT NOT NULL DEFAULT '',
            trip_id INTEGER,
            appointment_id TEXT NOT NULL DEFAULT '',
            created_at TEXT NOT NULL
        )"""
    )
    audit_columns = {row[1] for row in connection.execute("PRAGMA table_info(audit_log)").fetchall()}
    if "actor_user_id" not in audit_columns:
        connection.execute("ALTER TABLE audit_log ADD COLUMN actor_user_id INTEGER")
    if "actor_email" not in audit_columns:
        connection.execute("ALTER TABLE audit_log ADD COLUMN actor_email TEXT NOT NULL DEFAULT ''")
    connection.execute(
        """CREATE TABLE IF NOT EXISTS trip_appointments (
            appointment_id TEXT PRIMARY KEY,
            trip_id INTEGER NOT NULL,
            schedule_id INTEGER NOT NULL,
            visit_date TEXT NOT NULL,
            visit_time TEXT NOT NULL DEFAULT '',
            store_name TEXT NOT NULL,
            sequence_no INTEGER NOT NULL DEFAULT 0,
            updated_at TEXT NOT NULL
        )"""
    )
    table_names = {
        row[0]
        for row in connection.execute(
            "SELECT name FROM sqlite_master WHERE type='table'"
        ).fetchall()
    }
    if "road_visit_notes" in table_names:
        columns = {row[1] for row in connection.execute("PRAGMA table_info(road_visit_notes)").fetchall()}
        if "appointment_id" not in columns:
            connection.execute("ALTER TABLE road_visit_notes ADD COLUMN appointment_id TEXT NOT NULL DEFAULT ''")
    if "road_visit_attachments" in table_names:
        columns = {row[1] for row in connection.execute("PRAGMA table_info(road_visit_attachments)").fetchall()}
        if "appointment_id" not in columns:
            connection.execute("ALTER TABLE road_visit_attachments ADD COLUMN appointment_id TEXT NOT NULL DEFAULT ''")


def set_active_trip(trip_id):
    with db_connect() as connection:
        ensure_reliability_tables(connection)
        connection.execute(
            "INSERT INTO app_state (state_key,state_value,updated_at) VALUES (?,?,?) "
            "ON CONFLICT(state_key) DO UPDATE SET state_value=excluded.state_value,updated_at=excluded.updated_at",
            (_current_user_state_key("active_trip_id"), str(trip_id or ""), datetime.now().isoformat(timespec="seconds")),
        )
        connection.commit()


def get_active_trip_id():
    try:
        with db_connect() as connection:
            ensure_reliability_tables(connection)
            row = connection.execute(
                "SELECT state_value FROM app_state WHERE state_key=?", (_current_user_state_key("active_trip_id"),)
            ).fetchone()
            active_trip_id = int(row[0]) if row and row[0] else None
            owner_user_id = _trip_owner_user_id()
            if active_trip_id and owner_user_id is not None:
                trip = connection.execute(
                    "SELECT owner_user_id FROM trip_plans WHERE id=?", (active_trip_id,)
                ).fetchone()
                if trip and trip[0] is None:
                    # Legacy trips created before per-rep ownership was enforced can still be
                    # selected as the current user's active trip. Claim only that explicitly
                    # selected trip, preserving all linked schedules and history.
                    connection.execute(
                        "UPDATE trip_plans SET owner_user_id=? WHERE id=? AND owner_user_id IS NULL",
                        (owner_user_id, active_trip_id),
                    )
                    connection.execute(
                        "UPDATE trip_schedules SET owner_user_id=? WHERE trip_plan_id=? AND owner_user_id IS NULL",
                        (owner_user_id, active_trip_id),
                    )
            connection.commit()
    except (DB_ERRORS, TypeError, ValueError):
        return None
    return active_trip_id

ROUTE_DEFAULTS = {
    'rep_start': '07:00',
    'rep_end': '18:00',
    'customer_open': '08:00',
    'customer_close': '17:00',
}


def get_route_defaults():
    values = dict(ROUTE_DEFAULTS)
    try:
        with db_connect() as connection:
            ensure_reliability_tables(connection)
            rows = connection.execute(
                "SELECT state_key,state_value FROM app_state WHERE state_key IN ('route_rep_start','route_rep_end','route_customer_open','route_customer_close')"
            ).fetchall()
            connection.commit()
        mapping = {
            'route_rep_start': 'rep_start',
            'route_rep_end': 'rep_end',
            'route_customer_open': 'customer_open',
            'route_customer_close': 'customer_close',
        }

        for key, value in rows:
            if key in mapping and re.fullmatch(r'\d{2}:\d{2}', value or ''):
                values[mapping[key]] = value
    except DB_ERRORS:
        pass
    return values


def save_route_defaults(rep_start, rep_end, customer_open, customer_close):
    values = {
        'route_rep_start': rep_start,
        'route_rep_end': rep_end,
        'route_customer_open': customer_open,
        'route_customer_close': customer_close,
    }
    if not all(re.fullmatch(r'\d{2}:\d{2}', value or '') for value in values.values()):
        raise ValueError('All route-default times must be valid.')
    if rep_end <= rep_start:
        raise ValueError('Rep finish time must be later than rep start time.')
    if customer_close <= customer_open:
        raise ValueError('Customer closing time must be later than opening time.')
    now = datetime.now().isoformat(timespec='seconds')
    with db_connect() as connection:
        ensure_reliability_tables(connection)
        for key, value in values.items():
            connection.execute(
                "INSERT INTO app_state (state_key,state_value,updated_at) VALUES (?,?,?) ON CONFLICT(state_key) DO UPDATE SET state_value=excluded.state_value,updated_at=excluded.updated_at",
                (key, value, now),
            )
        connection.commit()

KPI_TARGET_DEFAULTS = {
    'calls_week': 0,
    'training_week': 0,
}


def get_kpi_targets():
    values = dict(KPI_TARGET_DEFAULTS)
    try:
        with db_connect() as connection:
            ensure_reliability_tables(connection)
            rows = connection.execute(
                "SELECT state_key,state_value FROM app_state WHERE state_key IN ('kpi_calls_week_target','kpi_training_week_target')"
            ).fetchall()
            connection.commit()
        mapping = {
            'kpi_calls_week_target': 'calls_week',
            'kpi_training_week_target': 'training_week',
        }
        for key, value in rows:
            if key in mapping:
                try:
                    values[mapping[key]] = max(0, int(value or 0))
                except (TypeError, ValueError):
                    pass
    except DB_ERRORS:
        pass
    return values


def save_kpi_targets(calls_week, training_week):
    try:
        calls_week = max(0, int(calls_week))
        training_week = max(0, int(training_week))
    except (TypeError, ValueError):
        raise ValueError('Weekly KPI targets must be whole numbers.')
    if calls_week > 500 or training_week > 100:
        raise ValueError('Weekly KPI targets are outside the expected range.')
    now = datetime.now().isoformat(timespec='seconds')
    with db_connect() as connection:
        ensure_reliability_tables(connection)
        for key, value in {
            'kpi_calls_week_target': calls_week,
            'kpi_training_week_target': training_week,
        }.items():
            connection.execute(
                "INSERT INTO app_state (state_key,state_value,updated_at) VALUES (?,?,?) ON CONFLICT(state_key) DO UPDATE SET state_value=excluded.state_value,updated_at=excluded.updated_at",
                (key, str(value), now),
            )
        connection.commit()


