def trip_readiness_status(plan):
    checks = [
        bool(plan.get("appointments_confirmed")),
        bool(plan.get("brochures_packed")),
        bool(plan.get("samples_packed")),
        bool(plan.get("briefs_reviewed")),
        bool(plan.get("travel_confirmed")),
    ]
    done = sum(checks)
    try:
        end_date = datetime.strptime(plan.get("end_date", ""), "%Y-%m-%d").date()
    except (TypeError, ValueError):
        end_date = None
    if end_date and end_date < date.today():
        return "complete", "Completed"
    if done == len(checks):
        return "ready", "Trip ready"
    booking_values = [plan.get("flight_status"), plan.get("rental_status"), plan.get("accommodation_status")]
    booking_problem = any(value in {"Not Booked", "Quote Received"} for value in booking_values)
    if booking_problem or (done and done < 3):
        return "attention", "Needs attention"
    if done >= 3:
        return "progress", "Planning underway"
    return "not-started", "Not started"


def build_year_planner(year, plans, selected_trip_id=None):
    trips_by_date = {}
    formatted_plans = []
    for record in plans:
        plan = dict(record)
        try:
            start = datetime.strptime(plan["start_date"], "%Y-%m-%d").date()
            end = datetime.strptime(plan["end_date"], "%Y-%m-%d").date()
        except (KeyError, TypeError, ValueError):
            continue
        status_key, status_label = trip_readiness_status(plan)
        plan.update({"status_key": status_key, "status_label": status_label})
        formatted_plans.append(plan)
        current = max(start, date(year, 1, 1))
        last = min(end, date(year, 12, 31))
        while current <= last:
            trips_by_date.setdefault(current, []).append(plan)
            current += timedelta(days=1)

    months = []
    today = nz_today()
    for month_number in range(1, 13):
        if month_number == 12:
            next_month = date(year + 1, 1, 1)
        else:
            next_month = date(year, month_number + 1, 1)
        days_in_month = (next_month - date(year, month_number, 1)).days
        days = []
        for day_number in range(1, days_in_month + 1):
            current = date(year, month_number, day_number)
            days.append({
                "day": day_number,
                "date": current.isoformat(),
                "weekday": current.strftime("%a")[:2],
                "weekend": current.weekday() >= 5,
                "today": current == today,
                "trips": trips_by_date.get(current, []),
            })
        months.append({"name": date(year, month_number, 1).strftime("%b"), "days": days})
    return months





def _historical_text(value):
    if value is None:
        return ""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value).strip()


def _historical_date(value):
    if isinstance(value, datetime):
        return value.date().isoformat()
    if isinstance(value, date):
        return value.isoformat()
    raw = _historical_text(value)
    if not raw:
        return ""
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y", "%m/%d/%Y"):
        try:
            return datetime.strptime(raw[:10], fmt).date().isoformat()
        except ValueError:
            continue
    return ""


def _historical_time(value):
    from datetime import time as _time
    if isinstance(value, datetime):
        return value.strftime("%H:%M")
    if isinstance(value, _time):
        return value.strftime("%H:%M")
    raw = _historical_text(value)
    if not raw:
        return ""
    for fmt in ("%H:%M:%S", "%H:%M", "%I:%M %p"):
        try:
            return datetime.strptime(raw, fmt).strftime("%H:%M")
        except ValueError:
            continue
    return raw[:5]


def _split_historical_call_note(raw_note):
    text = str(raw_note or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    if not text:
        return "", ""
    action_match = re.search(r"(?im)^\s*Actions\s*:\s*", text)
    note_match = re.search(r"(?im)^\s*Notes\s*:\s*", text)
    actions = ""
    notes = text
    if action_match and note_match and note_match.start() >= action_match.end():
        actions = text[action_match.end():note_match.start()].strip()
        notes = text[note_match.end():].strip()
    elif note_match:
        notes = text[note_match.end():].strip()
    elif action_match:
        actions = text[action_match.end():].strip()
        notes = ""
    action_lines = []
    for line in actions.splitlines():
        cleaned = re.sub(r"^\s*[-•]+\s*", "", line).strip()
        if cleaned:
            action_lines.append(cleaned)
    return "\n".join(action_lines).strip(), notes.strip()


def _historical_source_key(row):
    source_id = _historical_text(row.get("Portatour ID"))
    if source_id:
        return "report:" + source_id
    material = "|".join([
        _historical_date(row.get("Date")), _historical_time(row.get("Start")),
        _historical_text(row.get("Customer - Portatour ID")), _historical_text(row.get("Customer - Name")),
        _historical_text(row.get("Subject")), _historical_text(row.get("Note")),
    ])
    return "hash:" + hashlib.sha256(material.encode("utf-8")).hexdigest()


def parse_historical_call_workbook(raw_bytes, source_filename=""):
    """Parse the Reports export format into completed historical customer-call records."""
    workbook = load_workbook(BytesIO(raw_bytes), read_only=True, data_only=True)
    worksheet = workbook["Data"] if "Data" in workbook.sheetnames else workbook[workbook.sheetnames[0]]
    rows = worksheet.iter_rows(values_only=True)
    try:
        headers = [str(v or "").strip() for v in next(rows)]
    except StopIteration:
        return []
    required = {"Date", "Start", "Customer - Name"}
    missing = sorted(required.difference(headers))
    if missing:
        raise ValueError("The workbook is missing required column(s): " + ", ".join(missing))
    calls = []
    for values in rows:
        record = {headers[index]: values[index] if index < len(values) else None for index in range(len(headers))}
        subject = _historical_text(record.get("Subject"))
        report_type = _historical_text(record.get("Report type display name"))
        if report_type and report_type.casefold() != "call" and subject.casefold() != "call":
            continue
        if not report_type and subject and subject.casefold() != "call":
            continue
        store_name = _historical_text(record.get("Customer - Name"))
        visit_date = _historical_date(record.get("Date"))
        if not store_name or not visit_date:
            continue
        actions_text, visit_notes = _split_historical_call_note(record.get("Note"))
        try:
            duration = max(0, int(float(record.get("Duration") or 0)))
        except (TypeError, ValueError):
            duration = 0
        calls.append({
            "source_key": _historical_source_key(record),
            "source_report_id": _historical_text(record.get("Portatour ID")),
            "source_filename": source_filename,
            "store_name": store_name,
            "customer_external_id": _historical_text(record.get("Customer - External ID") or record.get("Customer - Customer #")),
            "customer_portatour_id": _historical_text(record.get("Customer - Portatour ID")),
            "customer_street": _historical_text(record.get("Customer - Street")),
            "customer_city": _historical_text(record.get("Customer - City")),
            "visit_date": visit_date,
            "start_time": _historical_time(record.get("Start")),
            "end_time": _historical_time(record.get("End time")),
            "duration_minutes": duration,
            "subject": subject or report_type or "Call",
            "visit_notes": visit_notes,
            "actions_text": actions_text,
            "raw_note": _historical_text(record.get("Note")),
            "rep_name": _historical_text(record.get("User - Name")),
            "rep_email": _historical_text(record.get("User - Email")),
        })
    workbook.close()
    return calls


def _historical_customer_maps(connection):
    connection.row_factory = sqlite3.Row
    customers = [dict(r) for r in connection.execute("SELECT * FROM route_customers").fetchall()]
    by_portatour, by_external, by_name, by_address = {}, {}, {}, {}
    for customer in customers:
        ptid = _customer_match_key(customer.get("portatour_id"))
        external = _customer_match_key(customer.get("external_id"))
        name = _customer_match_key(customer.get("name"))
        address = (_customer_match_key(customer.get("street")), _customer_match_key(customer.get("city")))
        if ptid:
            by_portatour[ptid] = customer
        if external:
            by_external[external] = customer
        if name:
            by_name[name] = customer
        if address[0]:
            by_address.setdefault(address, []).append(customer)
    return by_portatour, by_external, by_name, by_address


def _match_historical_customer(call, maps):
    by_portatour, by_external, by_name, by_address = maps
    ptid = _customer_match_key(call.get("customer_portatour_id"))
    external = _customer_match_key(call.get("customer_external_id"))
    name = _customer_match_key(call.get("store_name"))
    address = (_customer_match_key(call.get("customer_street")), _customer_match_key(call.get("customer_city")))
    if ptid and ptid in by_portatour:
        return by_portatour[ptid], "customer ID"
    if external and external in by_external:
        return by_external[external], "external ID"
    if name and name in by_name:
        return by_name[name], "customer name"
    candidates = by_address.get(address, []) if address[0] else []
    if len(candidates) == 1:
        return candidates[0], "address"
    return None, "unmatched"







def _activity_counts_for_user(connection, user_id, start_date, end_date=None):
    # Completed On-the-Road visits remain the primary KPI source.
    sql = """SELECT COUNT(*), COALESCE(SUM(CASE WHEN n.training_session=1 THEN 1 ELSE 0 END),0)
             FROM road_visit_notes n
             JOIN trip_schedules s ON s.id=n.schedule_id
             LEFT JOIN trip_plans p ON p.id=s.trip_plan_id
             WHERE COALESCE(n.owner_user_id,p.owner_user_id)=?
               AND n.completed=1 AND n.visit_date>=?"""
    params = [int(user_id), start_date]
    if end_date:
        sql += " AND n.visit_date<?"
        params.append(end_date)
    row = connection.execute(sql, tuple(params)).fetchone()
    calls = int((row[0] if row else 0) or 0)
    trainings = int((row[1] if row else 0) or 0)

    # Retrospective customer interactions are real completed activity too. They are
    # stored separately so they never create/alter a trip appointment, but they must
    # still count in the week/month in which they actually occurred. Match them to the
    # rep identity captured when the interaction was logged; this also covers manual
    # interactions created before this KPI integration existed.
    user = connection.execute(
        "SELECT email,display_name FROM app_users WHERE id=? LIMIT 1", (int(user_id),)
    ).fetchone()
    if user:
        try:
            email = str(user['email'] or '').strip().casefold()
            display_name = str(user['display_name'] or '').strip().casefold()
        except Exception:
            email = str(user[0] or '').strip().casefold()
            display_name = str(user[1] or '').strip().casefold()
        manual_sql = """SELECT COUNT(*), COALESCE(SUM(CASE WHEN COALESCE(training_session,0)=1 THEN 1 ELSE 0 END),0) FROM historical_customer_calls
                        WHERE source_report_id='manual_interaction'
                          AND visit_date>=?
                          AND ((?<>'' AND lower(trim(rep_email))=?)
                               OR (?<>'' AND lower(trim(rep_name))=?))"""
        manual_params = [start_date, email, email, display_name, display_name]
        if end_date:
            manual_sql += " AND visit_date<?"
            manual_params.append(end_date)
        manual_row = connection.execute(manual_sql, tuple(manual_params)).fetchone()
        calls += int((manual_row[0] if manual_row else 0) or 0)
        trainings += int((manual_row[1] if manual_row else 0) or 0)

    return calls, trainings


def _kpi_row_for_user(connection, user, week_start, month_start, targets):
    calls_week, training_week = _activity_counts_for_user(connection, int(user["id"]), week_start)
    calls_month, training_month = _activity_counts_for_user(connection, int(user["id"]), month_start)
    result = {
        "calls_week": calls_week, "training_week": training_week,
        "calls_month": calls_month, "training_month": training_month,
    }
    result["calls_percent"] = round(calls_week / targets["calls_week"] * 100) if targets["calls_week"] else 0
    result["training_percent"] = round(training_week / targets["training_week"] * 100) if targets["training_week"] else 0
    return result














@app.route("/team-dashboard")
@territory_manager_required
def team_dashboard():
    today = nz_today()
    team_tab = str(request.args.get("tab") or "overview").strip().lower()
    if team_tab == "calendar":
        team_tab = "trips"
    elif team_tab not in {"overview", "trips", "kpis"}:
        team_tab = "overview"
    try:
        requested_rep = int(request.args.get("rep") or 0)
    except (TypeError, ValueError):
        requested_rep = 0

    month_start = today.replace(day=1).isoformat()
    week_start = monday_for(today).isoformat()
    now_iso = today.isoformat()
    kpi_targets = get_kpi_targets()

    with db_connect() as connection:
        connection.row_factory = sqlite3.Row
        rep_options = [dict(r) for r in connection.execute(
            "SELECT id,email,display_name,role FROM app_users WHERE role IN ('sales_rep','manager','sales_manager') AND active=1 ORDER BY lower(display_name),lower(email)"
        ).fetchall()]
        valid_rep_ids = {int(r["id"]) for r in rep_options}
        selected_rep_id = requested_rep if requested_rep in valid_rep_ids else 0
        visible_reps = [r for r in rep_options if not selected_rep_id or int(r["id"]) == selected_rep_id]

        team_rows = []
        for rep in visible_reps:
            uid = int(rep["id"])
            customers = [dict(r) for r in connection.execute(
                "SELECT id,name,priority_tier,last_call,call_interval FROM route_customers WHERE assigned_user_id=?", (uid,)
            ).fetchall()]
            customer_ids = [int(c["id"]) for c in customers]
            latest_visits = _latest_customer_visit_dates(connection, customer_ids)
            overdue_customers = overdue_a = stale90 = 0
            for c in customers:
                latest_visit = latest_visits.get(int(c["id"]))
                state = _customer_visit_cycle_state(latest_visit["date"] if latest_visit else None, c.get("call_interval"), today)
                days = state["days_since"]
                overdue = state["overdue"]
                if overdue:
                    overdue_customers += 1
                    if str(c.get("priority_tier") or "").upper() == "A":
                        overdue_a += 1
                if days is None or days >= 90:
                    stale90 += 1
            coverage_percent = round((len(customers)-overdue_customers)/len(customers)*100) if customers else 100

            actions = [dict(r) for r in connection.execute(
                "SELECT priority,due_date FROM store_actions WHERE owner_user_id=? AND status!='Completed'", (uid,)
            ).fetchall()]
            overdue_actions = sum(1 for a in actions if a.get("due_date") and str(a["due_date"])[:10] < now_iso)
            high_actions = sum(1 for a in actions if a.get("priority") == "High")
            calls_week, training_week = _activity_counts_for_user(connection, uid, week_start)
            calls_month, training_month = _activity_counts_for_user(connection, uid, month_start)
            upcoming = [dict(r) for r in connection.execute(
                "SELECT id,trip_name,destination,start_date,end_date FROM trip_plans WHERE owner_user_id=? AND end_date>=? AND COALESCE(completed_at,'')='' ORDER BY start_date,id",
                (uid, now_iso),
            ).fetchall()]
            team_rows.append({
                **rep,
                "customer_count": len(customers), "overdue_customers": overdue_customers,
                "overdue_a": overdue_a, "stale90": stale90, "coverage_percent": coverage_percent,
                "open_actions": len(actions), "overdue_actions": overdue_actions, "high_actions": high_actions,
                "calls_week": int(calls_week or 0), "calls_month": int(calls_month or 0),
                "training_week": int(training_week or 0), "training_month": int(training_month or 0),
                "calls_percent": round(calls_week / kpi_targets["calls_week"] * 100) if kpi_targets["calls_week"] else 0,
                "training_percent": round(training_week / kpi_targets["training_week"] * 100) if kpi_targets["training_week"] else 0,
                "upcoming_trip_count": len(upcoming), "next_trip": upcoming[0] if upcoming else None,
            })

        weekly_activity = []
        current_monday = monday_for(today)
        for offset in range(8):
            start = current_monday - timedelta(days=7*offset)
            end = start + timedelta(days=7)
            row = {"week_start": start.isoformat(), "week_label": f"{start.day} {start.strftime('%b')}", "reps": []}
            for rep in visible_reps:
                calls, training = _activity_counts_for_user(connection, int(rep["id"]), start.isoformat(), end.isoformat())
                row["reps"].append({"id": int(rep["id"]), "name": rep["display_name"], "calls": calls, "training": training})
            weekly_activity.append(row)

        # Team annual trip planner: deliberately read-only, separate from personal Trip Prep.
        try:
            team_planner_year = int(request.args.get("year") or today.year)
        except (TypeError, ValueError):
            team_planner_year = today.year
        team_planner_year = min(max(team_planner_year, today.year - 5), today.year + 8)
        planner_sql = """SELECT p.*,u.display_name AS owner_display_name,u.email AS owner_email
                         FROM trip_plans p JOIN app_users u ON u.id=p.owner_user_id
                         WHERE u.active=1 AND u.role IN ('sales_rep','manager','sales_manager')
                           AND (substr(p.start_date,1,4)=? OR substr(p.end_date,1,4)=? OR (p.start_date < ? AND p.end_date > ?))"""
        planner_params = [str(team_planner_year), str(team_planner_year), f"{team_planner_year+1}-01-01", f"{team_planner_year}-01-01"]
        if selected_rep_id:
            planner_sql += " AND p.owner_user_id=?"
            planner_params.append(selected_rep_id)
        planner_sql += " ORDER BY p.start_date,p.id"
        planner_rows = [dict(r) for r in connection.execute(planner_sql, tuple(planner_params)).fetchall()]
        for row in planner_rows:
            row["owner_label"] = str(row.get("owner_display_name") or row.get("owner_email") or "Unassigned")
        team_planner_months = build_year_planner(team_planner_year, planner_rows)


    team_totals = {
        "reps": len(team_rows),
        "customers": sum(r["customer_count"] for r in team_rows),
        "overdue_customers": sum(r["overdue_customers"] for r in team_rows),
        "overdue_a": sum(r["overdue_a"] for r in team_rows),
        "overdue_actions": sum(r["overdue_actions"] for r in team_rows),
        "calls_week": sum(r["calls_week"] for r in team_rows),
        "training_week": sum(r["training_week"] for r in team_rows),
        "calls_month": sum(r["calls_month"] for r in team_rows),
        "training_month": sum(r["training_month"] for r in team_rows),
    }
    return render_template_string(
        PAGE, view="team_dashboard", team_tab=team_tab,
        team_rep_options=rep_options, team_selected_rep_id=selected_rep_id,
        team_rows=team_rows, team_totals=team_totals, weekly_activity=weekly_activity,
        kpi_targets=kpi_targets,
        team_planner_year=team_planner_year, team_planner_months=team_planner_months,
        open_action_count=get_open_action_count(),
    )


def _build_rescheduling_queue():
    today = nz_today()
    rows = []
    with db_connect() as connection:
        connection.row_factory = sqlite3.Row
        owner_user_id = _trip_owner_user_id()
        if owner_user_id is not None:
            trips = connection.execute(
                "SELECT * FROM trip_plans WHERE owner_user_id=? AND COALESCE(completed_at,'')='' AND end_date>=? ORDER BY start_date,id",
                (owner_user_id, today.isoformat()),
            ).fetchall()
        else:
            trips = connection.execute(
                "SELECT * FROM trip_plans WHERE COALESCE(completed_at,'')='' AND end_date>=? ORDER BY start_date,id",
                (today.isoformat(),),
            ).fetchall()
        customer_rows = connection.execute("SELECT * FROM route_customers").fetchall()
        customers = {str(r['name'] or '').strip().casefold(): dict(r) for r in customer_rows}
        for trip in trips:
            schedule = connection.execute("SELECT * FROM trip_schedules WHERE trip_plan_id=? ORDER BY id DESC LIMIT 1", (trip['id'],)).fetchone()
            if not schedule or not schedule['raw_html']:
                continue
            notes = {r['appointment_id']: r for r in connection.execute("SELECT * FROM road_visit_notes WHERE schedule_id=?", (schedule['id'],)).fetchall() if r['appointment_id']}
            soup = BeautifulSoup(schedule['raw_html'], 'html.parser')
            for day_div in soup.select('div.scheduleday'):
                class_date = next((c for c in day_div.get('class', []) if str(c).startswith('scheduleday_') and c != 'scheduleday'), '')
                try:
                    queue_date = datetime.strptime(class_date.replace('scheduleday_', ''), '%Y%m%d').date()
                except ValueError:
                    continue
                for row in day_div.select('tr.reschedule-stop'):
                    store = _schedule_store_from_row(row)
                    if not store:
                        continue
                    tm = _schedule_time_from_row(row)
                    appt_id = appointment_uid(trip['id'], schedule['id'], queue_date.isoformat(), tm, store)
                    note = notes.get(appt_id)
                    if note and (note['completed'] or ('skipped' in note.keys() and note['skipped'])):
                        continue
                    customer = customers.get(store.strip().casefold(), {})
                    customer_id = int(customer.get('id') or 0)
                    kind = _schedule_kind(row)
                    suggested = max(today, queue_date)
                    trip_end = datetime.strptime(str(trip['end_date'])[:10], '%Y-%m-%d').date()
                    if suggested > trip_end:
                        suggested = trip_end
                    rows.append({
                        'store': store,
                        'date_iso': queue_date.isoformat(),
                        'date_display': queue_date.strftime('%a %d %b %Y'),
                        'source_time': tm,
                        'time_display': _display_clock(tm),
                        'appointment_kind': kind,
                        'duration': _schedule_duration(row, customers),
                        'tier': str(customer.get('priority_tier') or 'C').upper(),
                        'reason': str(row.get('data-reschedule-reason') or 'Could not fit inside the valid call window.'),
                        'trip_id': int(trip['id']),
                        'trip_name': trip['trip_name'],
                        'trip_start': str(trip['start_date'])[:10],
                        'trip_end': str(trip['end_date'])[:10],
                        'suggested_date': suggested.isoformat(),
                        'customer_url': url_for('customer_detail_by_id', customer_id=customer_id) if customer_id else url_for('customer_detail', store_name=store),
                        'workspace_url': url_for('trip_workspace', trip_id=trip['id'], tab='schedule'),
                        'is_due': queue_date <= today,
                    })
    rows.sort(key=lambda x: (0 if x['is_due'] else 1, {'A':0,'B':1,'C':2,'D':3}.get(x.get('tier',''), 9), x['date_iso'], x['store'].casefold()))
    return rows




@app.route('/rescheduling')
def rescheduling_queue():
    rows = _build_rescheduling_queue()
    return render_template_string(
        PAGE,
        view='rescheduling',
        reschedule_rows=rows,
        reschedule_trip_count=len({r['trip_id'] for r in rows}),
        reschedule_a_count=sum(1 for r in rows if r.get('tier') == 'A'),
        reschedule_due_count=sum(1 for r in rows if r.get('is_due')),
        success=request.args.get('success'),
        error=request.args.get('error'),
        open_action_count=get_open_action_count(),
    )


TRIP_STATUSES = ["Planned", "Booked", "Completed", "Cancelled"]
BOOKING_STATUSES = ["Not Required", "Not Booked", "Booked"]
TRAVEL_COST_ITEMS = [
    {"key": "flights", "label": "Flights"},
    {"key": "rental", "label": "Rental Car"},
    {"key": "fuel", "label": "Fuel"},
    {"key": "accommodation", "label": "Accommodation"},
    {"key": "other", "label": "Other"},
]


def _travel_float(value):
    try:
        return max(float(value or 0), 0.0)
    except (TypeError, ValueError):
        return 0.0


def _normalize_booking_status(value):
    value = str(value or "").strip()
    if value in {"Booked", "Paid", "Completed"}:
        return "Booked"
    if value in {"Not Booked", "To Book"}:
        return "Not Booked"
    return "Not Required"


def travel_form_defaults(values=None):
    values = values or {}
    result = {
        "id": values.get("id", ""),
        "trip_name": values.get("trip_name", ""),
        "destination": values.get("destination", ""),
        "start_date": values.get("start_date", date.today().isoformat()),
        "end_date": values.get("end_date", date.today().isoformat()),
        "status": values.get("status", "Planned"),
        "flight_status": _normalize_booking_status(values.get("flight_status", "Not Required")),
        "rental_status": _normalize_booking_status(values.get("rental_status", "Not Required")),
        "accommodation_status": _normalize_booking_status(values.get("accommodation_status", "Not Required")),
        "notes": values.get("notes", ""),
    }
    for item in TRAVEL_COST_ITEMS:
        for prefix in ("forecast", "actual"):
            key = f"{prefix}_{item['key']}"
            value = values.get(key, 0)
            result[key] = "" if value in (None, 0, 0.0, "0", "0.0") else f"{float(value):.2f}"
    return result


def travel_row(record):
    row = dict(record)
    forecast = sum(float(row.get(f"forecast_{item['key']}", 0) or 0) for item in TRAVEL_COST_ITEMS)
    actual = sum(float(row.get(f"actual_{item['key']}", 0) or 0) for item in TRAVEL_COST_ITEMS)
    variance = actual - forecast
    start = datetime.strptime(row["start_date"], "%Y-%m-%d").date()
    end = datetime.strptime(row["end_date"], "%Y-%m-%d").date()
    row.update({
        "forecast": forecast,
        "actual": actual,
        "variance": variance,
        "forecast_display": money(forecast),
        "actual_display": money(actual),
        "variance_display": signed_money(variance),
        "variance_text_class": "variance-negative" if variance > 0 else "variance-positive",
        "date_display": f"{start.day} {start.strftime('%b %Y')}" if start == end else f"{start.day} {start.strftime('%b')} - {end.day} {end.strftime('%b %Y')}",
        "status_class": "travel-status-" + row["status"].lower().replace(" ", "-"),
    })
    return row















def infer_customer_group(name):
    value = str(name or '').lower()
    checks = [('bunnings','Bunnings'),('mitre 10 mega','Mitre 10 Mega'),('mitre10 mega','Mitre 10 Mega'),('mitre 10','Mitre 10'),('mitre10','Mitre 10'),('placemakers','Placemakers'),('place makers','Placemakers'),('carters','Carters'),('itm','ITM'),('hammer hardware','Hammer Hardware'),('buildlink','Buildlink')]
    for needle, label in checks:
        if needle in value: return label
    return 'Other'

def import_portatour_customers(uploaded_file):
    """Synchronise the live customer base to an authoritative Portatour export.

    Existing customers are updated in place so their durable route_customer ID is
    preserved. That keeps historical calls, sales history and other linked records
    attached to the same customer. Customers absent from the export are removed
    from the live customer table, while historical tables are deliberately left
    untouched. Customers present in the export but not yet in Riverlea Nexus are added.
    """
    frame = pd.read_excel(uploaded_file, sheet_name='Data')
    required = {'Name', 'Latitude', 'Longitude'}
    if not required.issubset(frame.columns):
        raise ValueError('The workbook must contain a Data sheet with Name, Latitude and Longitude columns.')

    def clean_value(value, default=''):
        if pd.isna(value):
            return default
        if isinstance(value, (pd.Timestamp, datetime)):
            return value.date().isoformat()
        return str(value).strip()

    source_rows = []
    seen_portatour = set()
    seen_external = set()
    seen_names = set()
    for row_number, (_, row) in enumerate(frame.iterrows(), start=2):
        name = clean_value(row.get('Name'))
        if not name:
            continue
        try:
            latitude = float(row.get('Latitude'))
            longitude = float(row.get('Longitude'))
        except (TypeError, ValueError):
            raise ValueError(f'Row {row_number} ({name}) is missing a valid latitude or longitude. No customers were changed.')

        external_id = clean_value(row.get('External ID')) or clean_value(row.get('Customer #'))
        portatour_id = clean_value(row.get('Portatour ID'))
        name_key = _customer_match_key(name)
        portatour_key = _customer_match_key(portatour_id)
        external_key = _customer_match_key(external_id)
        if portatour_key and portatour_key in seen_portatour:
            raise ValueError(f'Duplicate Portatour ID found in the export for {name}. No customers were changed.')
        if external_key and external_key in seen_external:
            raise ValueError(f'Duplicate External ID found in the export for {name}. No customers were changed.')
        if name_key in seen_names:
            raise ValueError(f'Duplicate customer name found in the export: {name}. No customers were changed.')
        if portatour_key:
            seen_portatour.add(portatour_key)
        if external_key:
            seen_external.add(external_key)
        seen_names.add(name_key)

        try:
            interval = max(1, int(float(row.get('Call interval', 42) or 42)))
        except (TypeError, ValueError):
            interval = 42
        try:
            duration = max(1, int(float(row.get('Call duration', 45) or 45)))
        except (TypeError, ValueError):
            duration = 45

        contacts = []
        for index in range(1, 6):
            contact_name = clean_value(row.get(f'Contact #{index}'))
            contact_email = clean_value(row.get(f'Email #{index}'))
            contact_phone = clean_value(row.get(f'Mobile #{index}'))
            if contact_name or contact_email or contact_phone:
                contacts.append({
                    'name': contact_name or f'Contact {index}',
                    'email': contact_email,
                    'phone': contact_phone,
                })

        source_rows.append({
            'external_id': external_id,
            'portatour_id': portatour_id,
            'name': name,
            'street': clean_value(row.get('Street')),
            'city': clean_value(row.get('City')),
            'zip': clean_value(row.get('ZIP')),
            'country': clean_value(row.get('Country'), 'New Zealand') or 'New Zealand',
            'customer_group': infer_customer_group(name),
            'categories': clean_value(row.get('Categories')),
            'priority_tier': (clean_value(row.get('Categories')).upper() if clean_value(row.get('Categories')).upper() in {'A','B','C','D'} else 'C'),
            'phone': clean_value(row.get('Phone')),
            'email': clean_value(row.get('Store Email')),
            'call_note': clean_value(row.get('Call Note')),
            'last_call': clean_value(row.get('Last call')),
            'call_interval': interval,
            'urgency': clean_value(row.get('Current urgency name')).lower(),
            'ideal_call_minutes': duration,
            'latitude': latitude,
            'longitude': longitude,
            'contacts': contacts,
        })

    if not source_rows:
        raise ValueError('The workbook contains no customer rows. No customers were changed.')

    now = datetime.now().isoformat(timespec='seconds')
    stats = {'updated': 0, 'added': 0, 'deleted': 0, 'contacts': 0, 'total': len(source_rows)}
    with db_connect() as connection:
        connection.row_factory = sqlite3.Row
        existing_rows = [dict(row) for row in connection.execute(
            'SELECT id,external_id,portatour_id,name FROM route_customers'
        ).fetchall()]
        by_portatour = {_customer_match_key(row.get('portatour_id')): row for row in existing_rows if _customer_match_key(row.get('portatour_id'))}
        by_external = {_customer_match_key(row.get('external_id')): row for row in existing_rows if _customer_match_key(row.get('external_id'))}
        by_name = {_customer_match_key(row.get('name')): row for row in existing_rows if _customer_match_key(row.get('name'))}
        retained_ids = set()

        for item in source_rows:
            existing = None
            pt_key = _customer_match_key(item['portatour_id'])
            external_key = _customer_match_key(item['external_id'])
            name_key = _customer_match_key(item['name'])
            if pt_key:
                existing = by_portatour.get(pt_key)
            if existing is None and external_key:
                existing = by_external.get(external_key)
            if existing is None:
                existing = by_name.get(name_key)

            values = (
                item['external_id'], item['portatour_id'], item['name'], item['street'], item['city'], item['zip'], item['country'],
                item['customer_group'], item['categories'], item['phone'], item['email'], item['call_note'], item['last_call'],
                item['call_interval'], item['urgency'], item['ideal_call_minutes'], item['priority_tier'], item['latitude'], item['longitude'], now,
            )
            if existing is not None:
                customer_id = int(existing['id'])
                connection.execute(
                    """UPDATE route_customers SET external_id=?,portatour_id=?,name=?,street=?,city=?,zip=?,country=?,customer_group=?,categories=?,phone=?,email=?,call_note=?,last_call=?,call_interval=?,urgency=?,ideal_call_minutes=?,priority_tier=?,latitude=?,longitude=?,updated_at=? WHERE id=?""",
                    values + (customer_id,),
                )
                stats['updated'] += 1
            else:
                cursor = connection.execute(
                    """INSERT INTO route_customers (external_id,portatour_id,name,street,city,zip,country,customer_group,categories,phone,email,call_note,last_call,call_interval,urgency,ideal_call_minutes,priority_tier,latitude,longitude,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    values,
                )
                customer_id = int(cursor.lastrowid)
                stats['added'] += 1

            retained_ids.add(customer_id)
            _sync_customer_name_snapshots(connection, customer_id, item['name'])
            # Contacts are part of this authoritative customer-base sync. Replace the
            # current contact list, but do not touch any historical call/sales records.
            old_name = str(existing.get('name') or '') if existing is not None else ''
            connection.execute('DELETE FROM customer_contacts WHERE customer_id=? OR lower(trim(store_name))=lower(trim(?)) OR lower(trim(store_name))=lower(trim(?))', (customer_id, item['name'], old_name))
            for contact in item['contacts']:
                connection.execute(
                    """INSERT INTO customer_contacts (store_name,customer_id,contact_name,role,phone,email,notes,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?)""",
                    (item['name'], customer_id, contact['name'], '', contact['phone'], contact['email'], '', now, now),
                )
                stats['contacts'] += 1

        delete_ids = [int(row['id']) for row in existing_rows if int(row['id']) not in retained_ids]
        if delete_ids:
            placeholders = ','.join('?' for _ in delete_ids)
            # Only the live customer directory is authoritative here. Historical calls,
            # sales, notes and audit records are intentionally retained in their own tables.
            connection.execute(f'DELETE FROM customer_contacts WHERE customer_id IN ({placeholders})', delete_ids)
            connection.execute(f'DELETE FROM route_customers WHERE id IN ({placeholders})', delete_ids)
            stats['deleted'] = len(delete_ids)

        connection.commit()
    return stats

def build_route_schedule_html(trip_name, start_date, route_payload):
    try:
        first_day = datetime.strptime(start_date, "%Y-%m-%d").date()
    except ValueError:
        first_day = date.today()
    overnight_mode=bool(route_payload.get('overnight_mode'))
    return_to_start=bool(route_payload.get('return_to_start_each_day'))
    travel_mode=str(route_payload.get('travel_mode') or 'drive').strip().lower()
    flight=route_payload.get('flight_constraints') or {}
    planner_state = dict(route_payload or {})
    planner_state_blob = base64.urlsafe_b64encode(json.dumps(planner_state, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).decode("ascii")
    chunks = [f"<html><head><meta charset='utf-8'><title>Riverlea Nexus Route</title></head><body data-route-planner='1' data-travel-mode='{escape(travel_mode)}' data-overnight-mode='{1 if overnight_mode else 0}' data-return-to-start='{1 if return_to_start else 0}' data-planner-state='{planner_state_blob}'>"]
    raw_route_days=route_payload.get("days", []) or []
    try:
        requested_day_count=max(1,int(route_payload.get("requested_day_count") or len(raw_route_days) or 1))
    except (TypeError,ValueError):
        requested_day_count=max(1,len(raw_route_days) or 1)
    requested_day_count=min(14,requested_day_count)
    indexed_days={}
    for pos, item in enumerate(raw_route_days):
        try:
            idx=int(item.get("day_index",pos))
        except (TypeError,ValueError):
            idx=pos
        indexed_days[idx]=dict(item or {})
    route_days=[]
    prior_finish=route_payload.get('start_point') or {}
    overnights=route_payload.get('overnight_locations') or []
    for idx in range(requested_day_count):
        day=dict(indexed_days.get(idx) or {})
        day['day_index']=idx
        if not day.get('start_point'):
            day['start_point']=prior_finish or route_payload.get('start_point') or {}
        if not day.get('finish_point'):
            overnight=overnights[idx] if idx < len(overnights) else {}
            if overnight and overnight.get('lat') is not None and overnight.get('lng') is not None:
                day['finish_point']=overnight
            elif idx==requested_day_count-1:
                day['finish_point']=route_payload.get('end_point') or day.get('start_point') or {}
            else:
                day['finish_point']=day.get('start_point') or {}
        prior_finish=day.get('finish_point') or prior_finish
        route_days.append(day)
    for day in route_days:
        day_index = int(day.get("day_index", 0))
        day_dates = route_payload.get("day_dates") or []
        try:
            visit_date = datetime.strptime(str(day_dates[day_index]), "%Y-%m-%d").date() if day_index < len(day_dates) else first_day + timedelta(days=day_index)
        except (ValueError, TypeError):
            visit_date = first_day + timedelta(days=day_index)
        day_start=day.get('start_point') or route_payload.get('start_point') or {}
        day_finish=day.get('finish_point') or route_payload.get('end_point') or day_start
        rep_start=escape(str(day.get('rep_start') or route_payload.get('rep_start') or '05:00'))
        rep_end=escape(str(day.get('rep_end') or route_payload.get('rep_end') or '19:00'))
        start_label=escape(str(day_start.get('label') or route_payload.get('start_point',{}).get('label') or 'Planned start location'))
        finish_label=escape(str(day_finish.get('label') or route_payload.get('end_point',{}).get('label') or start_label))
        # Route Planner already calculates the automatic lunch position for each day.
        # Persist that placement into the saved schedule immediately so a newly-created
        # Trip Workspace shows the same lunch break without requiring a re-optimise first.
        lunch_start=escape(str(day.get('lunch_start') or '').strip())
        try:
            lunch_duration=max(1,int(day.get('lunch_duration') or 30))
        except (TypeError,ValueError):
            lunch_duration=30
        lunch_attrs=(f" data-lunch-start='{lunch_start}' data-lunch-duration='{lunch_duration}'" if lunch_start else '')
        try:
            distance_km=max(0.0,float(day.get('distance_km') or 0))
        except (TypeError,ValueError):
            distance_km=0.0
        try:
            drive_minutes=max(0.0,float(day.get('drive_minutes') or 0))
        except (TypeError,ValueError):
            drive_minutes=0.0
        route_source=escape(str(day.get('route_source') or 'road'))
        chunks.append(f"<div class='scheduleday scheduleday_{visit_date.strftime('%Y%m%d')}' data-rep-start='{rep_start}' data-rep-end='{rep_end}' data-start-lat='{day_start.get('lat','')}' data-start-lng='{day_start.get('lng','')}' data-start-label='{start_label}' data-finish-lat='{day_finish.get('lat','')}' data-finish-lng='{day_finish.get('lng','')}' data-finish-label='{finish_label}' data-distance-km='{distance_km:.3f}' data-drive-minutes='{drive_minutes:.2f}' data-route-source='{route_source}'{lunch_attrs}>")
        chunks.append("<table>")
        if travel_mode in {'fly','mixed'} and str(flight.get('arrival_date') or '') == visit_date.isoformat():
            arrival_airport=escape(str((flight.get('arrival_airport') or {}).get('label') or start_label))
            arrival_time=escape(str(flight.get('arrival_time') or ''))
            ready_time=escape(str(flight.get('ready_time') or rep_start))
            chunks.append(f"<tr class='travel-anchor flight-arrival'><td class='time'>{arrival_time}</td><td class='reservation'>Flight arrival</td><td class='displayname'><div>✈ {arrival_airport}</div><div class='callnote'>⇒ Available to leave airport {ready_time}</div></td></tr>")
        # Persist calls and location-free blocked time in true chronological order.  This
        # keeps the saved schedule, Workspace and Calendar aligned with the actual day
        # timeline rather than pinning time blocks to the top of the day.
        timeline_rows=[]
        for block in route_payload.get('custom_time_blocks', []):
            if int(block.get('dayIndex',-1)) != day_index:
                continue
            block_name=escape(str(block.get('name') or 'Blocked time'))
            block_time=escape(str(block.get('time') or ''))
            try:
                block_duration=max(5,int(block.get('duration') or 60))
            except (TypeError,ValueError):
                block_duration=60
            timeline_rows.append((str(block.get('time') or ''),0,'block',{
                'name':block_name,'time':block_time,'duration':block_duration,
            }))
        for stop in day.get('stops', []):
            timeline_rows.append((str(stop.get('arrival') or ''),1,'stop',stop))
        timeline_rows.sort(key=lambda item:(item[0],item[1]))
        for _,__,row_kind,row_data in timeline_rows:
            if row_kind=='block':
                chunks.append(f"<tr class='custom-stop' data-custom-type='block' data-duration='{row_data['duration']}' data-location-label=''><td class='time'>{row_data['time']}</td><td class='reservation'>Blocked time</td><td class='displayname'><div>{row_data['name']}</div><div class='callnote'>⇒ {row_data['duration']} minutes reserved</div></td></tr>")
                continue
            stop=row_data
            name = escape(str(stop.get('name', 'Customer')))
            arrival = escape(str(stop.get('arrival', '')))
            note = escape(str(stop.get('call_note', '')))
            duration = int(stop.get('duration', 45) or 45)
            if stop.get('is_custom'):
                custom_type=escape(str(stop.get('custom_type') or 'appointment'))
                location_label=escape(str(stop.get('location_label') or stop.get('city') or 'Custom location'))
                latitude=escape(str(stop.get('latitude') or ''))
                longitude=escape(str(stop.get('longitude') or ''))
                chunks.append(f"<tr class='custom-stop' data-custom-type='{custom_type}' data-duration='{duration}' data-location-label='{location_label}' data-latitude='{latitude}' data-longitude='{longitude}'>")
                chunks.append(f"<td class='time'>{arrival}</td><td class='reservation'>Custom stop</td><td class='displayname'><div>{name}</div><div class='callnote'>⇒ {location_label} · {duration} minutes</div></td></tr>")
                continue
            note_text = f"Route Planner · {duration} minute visit" + (f" · {note}" if note else "")
            customer_id = int(stop.get('customer_id') or 0)
            appointment_kind = escape(str(stop.get('appointment_kind') or ("locked" if stop.get('locked') else "")))
            preferred_time = escape(str(stop.get('preferred_time') or ""))
            timing_warning = escape(str(stop.get('timing_warning') or ""))
            chunks.append(f"<tr class='stop' data-customer-id='{customer_id}' data-duration='{duration}' data-appointment-kind='{appointment_kind}' data-preferred-time='{preferred_time}' data-timing-warning='{timing_warning}'>")
            chunks.append(f"<td class='time'>{arrival}</td><td class='reservation'>Appointment</td>")
            chunks.append(f"<td class='displayname'><div>{name}</div><div class='callnote'>⇒ {note_text}</div></td>")
            chunks.append("</tr>")
        if travel_mode in {'fly','mixed'} and str(flight.get('departure_date') or '') == visit_date.isoformat():
            departure_airport=escape(str((flight.get('departure_airport') or {}).get('label') or finish_label))
            airport_deadline=escape(str(flight.get('airport_deadline') or rep_end))
            departure_time=escape(str(flight.get('departure_time') or ''))
            chunks.append(f"<tr class='travel-anchor flight-departure'><td class='time'>{airport_deadline}</td><td class='reservation'>Airport deadline</td><td class='displayname'><div>✈ {departure_airport}</div><div class='callnote'>⇒ Flight departs {departure_time}</div></td></tr>")
        chunks.append("</table></div>")
    chunks.append("</body></html>")
    return "".join(chunks)


def _normalise_date_input(value):
    text=str(value or '').strip()
    if not text:
        return ''
    for fmt in ('%Y-%m-%d','%d/%m/%Y','%d-%m-%Y','%Y/%m/%d'):
        try:
            return datetime.strptime(text[:10],fmt).date().isoformat()
        except ValueError:
            pass
    return ''



def _workspace_time_minutes(value):
    """Parse either stored 24-hour times or human-facing 12-hour times into minutes."""
    text=str(value or '').strip()
    match=re.search(r'(\d{1,2}):(\d{2})\s*([ap]m)?',text,flags=re.I)
    if not match:
        return 8*60
    hour=int(match.group(1)); minute=int(match.group(2)); suffix=(match.group(3) or '').lower()
    if suffix:
        hour=(hour%12)+(12 if suffix=='pm' else 0)
    if hour>23 or minute>59:
        return 8*60
    return hour*60+minute


def _workspace_clock(minutes):
    minutes=int(minutes)%1440
    return f"{minutes//60:02d}:{minutes%60:02d}"


def _display_clock(value):
    """Return a human-facing 12-hour clock while leaving stored times in HH:MM."""
    if isinstance(value, (int, float)):
        minutes=int(round(value))%1440
    else:
        text=str(value or '').strip()
        match=re.search(r'(\d{1,2}):(\d{2})\s*([ap]m)?',text,flags=re.I)
        if not match:
            return text
        hour=int(match.group(1)); minute=int(match.group(2)); suffix_in=(match.group(3) or '').lower()
        if suffix_in:
            hour=(hour%12)+(12 if suffix_in=='pm' else 0)
        minutes=(hour%24)*60+minute
    hour=(minutes//60)%24
    minute=minutes%60
    suffix='am' if hour<12 else 'pm'
    hour12=hour%12 or 12
    return f"{hour12}:{minute:02d} {suffix}"


app.jinja_env.filters['time12']=_display_clock


def _workspace_haversine(lat1,lon1,lat2,lon2):
    from math import radians,sin,cos,asin,sqrt
    r=6371.0; dlat=radians(lat2-lat1); dlon=radians(lon2-lon1)
    q=sin(dlat/2)**2+cos(radians(lat1))*cos(radians(lat2))*sin(dlon/2)**2
    return 2*r*asin(sqrt(q))


def _schedule_store_from_row(row):
    display=row.select_one('td.displayname')
    if not display:
        return ''
    direct_divs=display.find_all('div',recursive=False)
    return (direct_divs[0].get_text(' ',strip=True) if direct_divs else display.get_text(' ',strip=True)).strip()


def _schedule_time_from_row(row):
    cell=row.select_one('td.time')
    return cell.get_text(' ',strip=True) if cell else ''


def _schedule_customer_id(row, customer_by_name):
    raw=str(row.get('data-customer-id') or '').strip()
    if raw.isdigit():
        return int(raw)
    customer=customer_by_name.get(_schedule_store_from_row(row).casefold()) or {}
    return int(customer.get('id') or 0)


def _schedule_duration(row, customer_by_name):
    raw=str(row.get('data-duration') or '').strip()
    if raw.isdigit() and int(raw)>0:
        return max(10,int(raw))
    customer=customer_by_name.get(_schedule_store_from_row(row).casefold()) or {}
    return max(10,int(customer.get('ideal_call_minutes') or 45))


def _schedule_kind(row):
    kind=str(row.get('data-appointment-kind') or '').strip().lower()
    if kind == 'preferred':
        return 'leeway'
    if kind in {'locked','leeway','flexible'}:
        return kind
    display=row.select_one('div.callnote')
    note=display.get_text(' ',strip=True).lower() if display else ''
    return 'locked' if ('locked' in note or 'fixed' in note) else ('leeway' if ('preferred' in note or 'leeway' in note) else 'flexible')


def _schedule_estimated_travel_minutes(row_a,row_b,customer_by_name):
    if row_a is None or row_b is None:
        return 0
    a=customer_by_name.get(_schedule_store_from_row(row_a).casefold()) or {}
    b=customer_by_name.get(_schedule_store_from_row(row_b).casefold()) or {}
    try:
        km=_workspace_haversine(float(a.get('latitude')),float(a.get('longitude')),float(b.get('latitude')),float(b.get('longitude')))*1.28
        return max(3,round(km/67*60))
    except (TypeError,ValueError):
        return 5


def _trip_schedule_day_div(soup, target_date, create=False):
    class_name=f"scheduleday_{target_date.strftime('%Y%m%d')}"
    for day_div in soup.select('div.scheduleday'):
        if class_name in day_div.get('class',[]):
            return day_div
    if not create:
        return None
    day_div=soup.new_tag('div')
    day_div['class']=['scheduleday',class_name]
    table=soup.new_tag('table')
    day_div.append(table)
    body=soup.body or soup
    body.append(day_div)
    return day_div


def _road_duration_matrix(points):
    """Return pairwise driving minutes, preferring OSRM and falling back to local estimates.

    The maths and fallback are unchanged; they now live in core.routing.road_matrix,
    which also reports whether the numbers are real road times. The source of the
    most recent matrix is kept in _LAST_ROAD_MATRIX_SOURCE for diagnostics.
    """
    global _LAST_ROAD_MATRIX_SOURCE
    result = road_matrix(points, timeout=6, want_distance=False)
    _LAST_ROAD_MATRIX_SOURCE = result.get("source", "estimate")
    return result["minutes"]


_LAST_ROAD_MATRIX_SOURCE = ""


def _reschedule_trip_appointment(trip_id, schedule, old_date, old_time, store_name, new_date, new_time, kind, call_duration=None):
    """Move one appointment, then re-optimise the target day around all hard commitments."""
    if kind == 'preferred':
        kind='leeway'
    if kind not in {'locked','leeway','flexible'}:
        kind='locked'
    try:
        old_day=datetime.strptime(old_date,'%Y-%m-%d').date()
        target_day=datetime.strptime(new_date,'%Y-%m-%d').date()
    except ValueError:
        return False,'Choose a valid appointment date.'
    if not re.fullmatch(r'\d{2}:\d{2}',str(new_time or '')):
        return False,'Choose a valid appointment time.'
    target_minutes=_workspace_time_minutes(new_time)
    try:
        requested_duration=int(call_duration) if call_duration not in (None,'') else None
    except (TypeError,ValueError):
        return False,'Choose a valid call length.'
    if requested_duration is not None and not 10 <= requested_duration <= 240:
        return False,'Call length must be between 10 and 240 minutes.'

    with db_connect() as connection:
        connection.row_factory=sqlite3.Row
        trip=_trip_row_for_current_user(connection,trip_id)
        if not trip:
            return False,'Trip not found.'
        try:
            trip_start=datetime.strptime(trip['start_date'],'%Y-%m-%d').date()
            trip_end=datetime.strptime(trip['end_date'],'%Y-%m-%d').date()
        except Exception:
            trip_start=target_day; trip_end=target_day
        if target_day<trip_start or target_day>trip_end:
            return False,f"Choose a date between {trip_start.strftime('%d %b')} and {trip_end.strftime('%d %b %Y')}."

        customer_rows=[dict(r) for r in connection.execute('SELECT * FROM route_customers').fetchall()]
        customer_by_name={str(r.get('name') or '').strip().casefold():r for r in customer_rows if r.get('name')}
        soup=BeautifulSoup(schedule['raw_html'],'html.parser')
        source_day=_trip_schedule_day_div(soup,old_day,False)
        if not source_day:
            return False,'The original appointment day could not be found.'

        target_row=None
        wanted_store=str(store_name or '').strip().casefold()
        for row in source_day.select('tr.stop, tr.reschedule-stop'):
            if _schedule_store_from_row(row).casefold()==wanted_store and _workspace_time_minutes(_schedule_time_from_row(row))==_workspace_time_minutes(old_time):
                target_row=row; break
        if target_row is None:
            return False,'That appointment could not be found in the saved trip schedule.'

        old_uid=appointment_uid(trip_id,schedule['id'],old_day.isoformat(),old_time,store_name)
        completed=connection.execute('SELECT completed FROM road_visit_notes WHERE appointment_id=? LIMIT 1',(old_uid,)).fetchone()
        if completed and completed[0]:
            return False,'Completed visits cannot be rescheduled.'

        # Capture current identities before changing dates/times so linked records can follow safely.
        identity={}
        for day_div in soup.select('div.scheduleday'):
            class_date=next((c for c in day_div.get('class',[]) if c.startswith('scheduleday_') and c!='scheduleday'),'')
            try: d=datetime.strptime(class_date.replace('scheduleday_',''),'%Y%m%d').date()
            except ValueError: continue
            for row in day_div.select('tr.stop, tr.reschedule-stop'):
                st=_schedule_store_from_row(row); tm=_schedule_time_from_row(row)
                identity[id(row)]={'date':d,'time':tm,'store':st,'uid':appointment_uid(trip_id,schedule['id'],d.isoformat(),tm,st)}

        target_day_div=_trip_schedule_day_div(soup,target_day,True)
        target_table=target_day_div.find('table')
        if target_row.parent is not target_table:
            target_row.extract(); target_table.append(target_row)
        target_row['data-appointment-kind']=kind
        if requested_duration is not None:
            target_row['data-duration']=str(requested_duration)
        else:
            target_row['data-duration']=str(_schedule_duration(target_row,customer_by_name))
        customer_id=_schedule_customer_id(target_row,customer_by_name)
        if customer_id:
            target_row['data-customer-id']=str(customer_id)
        target_row.select_one('td.time').string=_workspace_clock(target_minutes)

        rows=list(target_day_div.select('tr.stop, tr.reschedule-stop'))
        if not rows:
            return False,'There are no appointments on that day to optimise.'

        # Newer Route-Planner schedules carry the real day anchors. Older trips fall back to
        # the established Hamilton base and normal 5am-7pm sales day used by this app.
        def attr_float(name,default):
            try: return float(target_day_div.get(name))
            except (TypeError,ValueError): return default
        start_point={'lat':attr_float('data-start-lat',-37.7870),'lng':attr_float('data-start-lng',175.2793)}
        finish_point={'lat':attr_float('data-finish-lat',start_point['lat']),'lng':attr_float('data-finish-lng',start_point['lng'])}
        rep_start=_workspace_time_minutes(target_day_div.get('data-rep-start') or '05:00')
        rep_end=_workspace_time_minutes(target_day_div.get('data-rep-end') or '19:00')

        items=[]
        for row in rows:
            customer=customer_by_name.get(_schedule_store_from_row(row).casefold()) or {}
            try:
                lat=float(customer.get('latitude')); lng=float(customer.get('longitude'))
            except (TypeError,ValueError):
                return False,f"{_schedule_store_from_row(row)} does not have usable map coordinates."
            duration=_schedule_duration(row,customer_by_name)
            original_minutes=_workspace_time_minutes(_schedule_time_from_row(row))
            row_kind=_schedule_kind(row)
            preferred_attr=str(row.get('data-preferred-time') or customer.get('preferred_visit_time') or '').strip()
            preferred_minutes=_workspace_time_minutes(preferred_attr) if re.fullmatch(r'\d{2}:\d{2}',preferred_attr) else None
            if row is target_row:
                row_kind=kind; original_minutes=target_minutes
                if kind=='leeway': preferred_minutes=target_minutes
            elif row_kind in {'leeway','preferred'} and preferred_minutes is not None:
                original_minutes=preferred_minutes
            info=identity.get(id(row))
            is_completed=False
            if info:
                rec=connection.execute('SELECT completed FROM road_visit_notes WHERE appointment_id=? LIMIT 1',(info['uid'],)).fetchone()
                is_completed=bool(rec and rec[0])
            # Customer calls are only allowed between 8:00 am and 5:00 pm.
            # The rep may depart earlier for travel, and may return after 5:00 pm within rep hours.
            open_min=max(8*60,_workspace_time_minutes(customer.get('customer_open_time') or '08:00'))
            close_min=min(17*60,_workspace_time_minutes(customer.get('customer_close_time') or '17:00'))
            tier=str(customer.get('priority_tier') or 'C').upper()
            items.append({'row':row,'name':_schedule_store_from_row(row),'lat':lat,'lng':lng,'duration':duration,
                          'kind':row_kind,'desired':original_minutes,'hard':is_completed or row_kind=='locked',
                          'completed':is_completed,'open':open_min,'close':close_min,'tier':tier,
                          'preferred_time':preferred_minutes})

        hard=sorted([x for x in items if x['hard']],key=lambda x:x['desired'])
        for a,b in zip(hard,hard[1:]):
            if a['desired']+a['duration']>b['desired']:
                return False,f"Confirmed/completed appointments {a['name']} and {b['name']} overlap."

        # Build one road-time matrix for the whole day. This is the same real-road principle
        # used by Route Planner, with the same local-distance fallback if the free service is unavailable.
        points=[start_point]+[{'lat':x['lat'],'lng':x['lng']} for x in items]+[finish_point]
        matrix=_road_duration_matrix(points)
        point_index={id(x['row']):i+1 for i,x in enumerate(items)}
        start_idx=0; finish_idx=len(points)-1
        remaining=[x for x in items if not x['hard']]
        ordered=[]
        cursor=rep_start
        location_idx=start_idx
        lunch_taken=False
        lunch_start_record=None

        def maybe_take_lunch(now,next_deadline=None,travel_to_deadline=0):
            nonlocal lunch_taken,lunch_start_record
            if lunch_taken or now>=13*60:
                return now
            # Do NOT jump a free morning forward to 11:00 just to take lunch.
            # Before 11:00 the optimiser should keep filling useful customer calls.
            # Lunch is only inserted once the live route clock has actually reached
            # the lunch window (11:00 am-1:00 pm).
            if now < 11*60:
                return now
            lunch_start=now
            # If there is a confirmed/completed appointment ahead, lunch is only allowed
            # when there is still enough time to finish lunch AND drive to that hard anchor.
            latest_lunch_finish = None if next_deadline is None else next_deadline-max(0,float(travel_to_deadline or 0))
            if lunch_start<=12*60+30 and (latest_lunch_finish is None or lunch_start+30<=latest_lunch_finish+0.5):
                lunch_taken=True
                lunch_start_record=int(round(lunch_start))
                return lunch_start+30
            return now

        def candidate_plan(item,now,from_idx,next_hard=None,relax_leeway=False):
            travel=matrix[from_idx][point_index[id(item['row'])]]
            natural_arrival=max(now+travel,item['open'])
            arrival=natural_arrival
            leeway_miss=False
            if item['kind'] in {'leeway','preferred'}:
                earliest=max(item['open'],item['desired']-60)
                latest=min(item['close']-item['duration'],item['desired']+60)
                if relax_leeway:
                    arrival=natural_arrival
                    leeway_miss=arrival<earliest-0.5 or arrival>latest+0.5
                else:
                    arrival=max(natural_arrival,earliest)
                    if arrival>latest+0.5:
                        return None
            finish=arrival+item['duration']
            if finish>item['close'] or finish>rep_end:
                return None
            if next_hard is not None:
                onward=matrix[point_index[id(item['row'])]][point_index[id(next_hard['row'])]]
                if finish+onward>next_hard['desired']+0.5:
                    return None
            else:
                # Any last customer call may finish by 5:00 pm, but there still needs to be
                # enough rep time to drive to the planned finish location afterwards.
                if finish+matrix[point_index[id(item['row'])]][finish_idx]>rep_end+0.5:
                    return None
            # With-leeway appointments may move up to one hour either side, but still prefer the requested time.
            preference_penalty=abs(arrival-item['desired'])*0.35 if item['kind'] in {'leeway','preferred'} else 0
            # Customer tier must NOT dictate chronological order. Route efficiency and
            # time-window fit decide where a call goes. Tier is only used later as a
            # retention safeguard if choosing a lower-tier call would strand a higher-tier
            # call and push it into Needs Rescheduling.
            # At the beginning of the day, strongly prefer a feasible 8:00 am first call.
            # Travel may start earlier, but customer-facing appointments should not drift to mid-morning.
            first_call_penalty=max(0,arrival-8*60)*250 if not ordered else 0
            score=travel+preference_penalty+first_call_penalty
            if next_hard is not None:
                # A fixed appointment splits the day into two scheduling windows.  Do not simply
                # fill the first window with the nearest short calls, because that can strand long
                # or distant calls after the fixed appointment.  Give priority before the anchor to
                # calls that would be expensive to leave until afterwards (drive from the anchor +
                # visit duration + progress toward the planned finish point).
                anchor_idx=point_index[id(next_hard['row'])]
                item_idx=point_index[id(item['row'])]
                after_anchor_cost=(
                    matrix[anchor_idx][item_idx]
                    + item['duration']
                    + 0.35*matrix[item_idx][finish_idx]
                )
                score -= 0.72*after_anchor_cost
            return {'arrival':arrival,'finish':finish,'score':score + (100000 if leeway_miss else 0),'leeway_miss':leeway_miss}

        for commitment in hard+[None]:
            deadline=commitment['desired'] if commitment else None
            while remaining:
                # When a confirmed/completed appointment is ahead, reserve the REAL road
                # travel time from the current location before deciding whether lunch fits.
                # Previously this call passed the deadline but implicitly used zero travel,
                # so a 30-minute lunch could consume the drive buffer and make an otherwise
                # feasible fixed appointment look unreachable.
                travel_to_commitment = (
                    matrix[location_idx][point_index[id(commitment['row'])]]
                    if commitment is not None else 0
                )
                cursor=maybe_take_lunch(cursor,deadline,travel_to_commitment)
                plans=[]
                tier_rank={'A':0,'B':1,'C':2,'D':3}
                for item in remaining:
                    plan=candidate_plan(item,cursor,location_idx,commitment)
                    # Treat leeway as a real window. Only allow an outside-window fallback
                    # when this scheduling window is constrained by a fixed appointment.
                    # Otherwise we must wait/reorder rather than quietly ignore the preference.
                    if plan is None and commitment is not None and item['kind'] in {'leeway','preferred'}:
                        plan=candidate_plan(item,cursor,location_idx,commitment,True)
                    if plan:
                        adjusted_score=plan['score']
                        item_rank=tier_rank.get(item.get('tier','C'),2)
                        item_idx=point_index[id(item['row'])]
                        # Tier is a KEEP/DROP priority only. We do not move A customers to
                        # the front simply because they are A. Instead, penalise a lower-tier
                        # choice only when taking it now would make a higher-tier call that is
                        # currently feasible become impossible to fit in this scheduling window,
                        # and that higher-tier call cannot safely be deferred until after the
                        # next confirmed appointment.
                        for protected in remaining:
                            if protected is item or tier_rank.get(protected.get('tier','C'),2) >= item_rank:
                                continue
                            before=candidate_plan(protected,cursor,location_idx,commitment)
                            if not before:
                                continue
                            after=candidate_plan(protected,plan['finish'],item_idx,commitment)
                            if after:
                                continue
                            can_defer=False
                            if commitment is not None:
                                anchor_idx=point_index[id(commitment['row'])]
                                anchor_finish=commitment['desired']+commitment['duration']
                                can_defer=candidate_plan(protected,anchor_finish,anchor_idx,None) is not None
                            if not can_defer:
                                adjusted_score += 100000
                                break
                        plans.append((adjusted_score,plan['arrival'],item,plan))
                if not plans:
                    break
                plans.sort(key=lambda x:(x[0],x[1]))
                _,_,chosen,plan=plans[0]
                chosen['new_start']=int(round(plan['arrival']))
                chosen['leeway_miss']=bool(plan.get('leeway_miss'))
                ordered.append(chosen)
                cursor=plan['finish']
                location_idx=point_index[id(chosen['row'])]
                remaining.remove(chosen)

            if commitment is not None:
                travel=matrix[location_idx][point_index[id(commitment['row'])]]
                cursor=maybe_take_lunch(cursor,commitment['desired'],travel)
                if cursor+travel>commitment['desired']+0.5:
                    return False,f"The route cannot reach confirmed appointment {commitment['name']} by {_display_clock(commitment['desired'])} from the preceding stop."
                if commitment['desired']<commitment['open'] or commitment['desired']+commitment['duration']>commitment['close']:
                    return False,f"{commitment['name']} at {_display_clock(commitment['desired'])} falls outside its customer opening hours."
                commitment['new_start']=commitment['desired']
                ordered.append(commitment)
                cursor=commitment['desired']+commitment['duration']
                location_idx=point_index[id(commitment['row'])]

        # Calls that genuinely cannot fit are not allowed to invalidate the whole reset.
        # Pull them out of the live schedule so they can be manually rescheduled.
        overflow=list(remaining)

        # Final hard guard: never persist a re-optimised call outside that customer's own
        # trading hours. This deliberately checks the finished schedule again rather than
        # relying only on candidate insertion logic.
        for item in ordered:
            start_min=int(item.get('new_start',item['desired']))
            finish_min=start_min+int(item['duration'])
            if start_min < item['open'] or finish_min > item['close']:
                return False,(f"{item['name']} would run {_display_clock(start_min)}–{_display_clock(finish_min)}, "
                              f"outside its customer hours {_display_clock(item['open'])}–{_display_clock(item['close'])}. "
                              "The schedule has not been changed.")

        cursor=maybe_take_lunch(cursor,None)
        if cursor+matrix[location_idx][finish_idx]>rep_end+0.5:
            return False,'The fixed appointments themselves leave no way to return within the configured rep finish time.'

        # Persist lunch placement so Trip Workspace can display it in the day timeline.
        if lunch_start_record is not None:
            target_day_div['data-lunch-start']=_workspace_clock(lunch_start_record)
            target_day_div['data-lunch-duration']='30'
        else:
            target_day_div.attrs.pop('data-lunch-start',None)
            target_day_div.attrs.pop('data-lunch-duration',None)

        # Write the valid schedule first. Overflow calls remain attached to the trip but are
        # deliberately excluded from the active schedule until manually rescheduled.
        for item in ordered:
            item['row'].select_one('td.time').string=_workspace_clock(item['new_start'])
            item['row']['class']=['stop']
            if item['kind'] in {'leeway','preferred'}:
                item['row']['data-preferred-time']=_workspace_clock(item['desired'])
                if item.get('leeway_miss'):
                    item['row']['data-timing-warning']=(f"Preferred {_workspace_clock(item['desired'])}; scheduled {_workspace_clock(item['new_start'])} outside ±1 hour window")
                else:
                    item['row'].attrs.pop('data-timing-warning',None)
            else:
                item['row'].attrs.pop('data-timing-warning',None)
            if item['row'].has_attr('data-reschedule-reason'):
                del item['row']['data-reschedule-reason']
        for item in overflow:
            item['row']['class']=['reschedule-stop']
            item['row']['data-reschedule-reason']='Could not fit between 8:00 am and 5:00 pm while respecting fixed appointments, customer hours and travel time.'
        for row in list(target_table.select('tr.stop, tr.reschedule-stop')):
            row.extract()
        for item in ordered:
            target_table.append(item['row'])
        for item in sorted(overflow,key=lambda x:({'A':0,'B':1,'C':2,'D':3}.get(x.get('tier','C'),2),x['name'])):
            target_table.append(item['row'])

        now=datetime.now().isoformat(timespec='seconds')
        connection.execute('UPDATE trip_schedules SET raw_html=?, uploaded_at=? WHERE id=?',(str(soup),now,schedule['id']))

        # Migrate objectives, visit notes, attachment metadata and reliability IDs for every changed call.
        changes=[]; sequence=0
        for day_div in soup.select('div.scheduleday'):
            class_date=next((c for c in day_div.get('class',[]) if c.startswith('scheduleday_') and c!='scheduleday'),'')
            try: d=datetime.strptime(class_date.replace('scheduleday_',''),'%Y%m%d').date()
            except ValueError: continue
            for row in day_div.select('tr.stop, tr.reschedule-stop'):
                sequence+=1
                st=_schedule_store_from_row(row); tm=_schedule_time_from_row(row)
                prior=identity.get(id(row))
                if not prior: continue
                new_uid=appointment_uid(trip_id,schedule['id'],d.isoformat(),tm,st)
                if new_uid!=prior['uid']:
                    changes.append({'old_uid':prior['uid'],'new_uid':new_uid,'date':d.isoformat(),'time':tm,'sequence':sequence})
        for idx,change in enumerate(changes):
            temp_uid=f"__reschedule__{trip_id}_{schedule['id']}_{idx}_{change['old_uid']}"
            change['temp_uid']=temp_uid
            connection.execute('UPDATE appointment_objectives SET appointment_id=? WHERE appointment_id=?',(temp_uid,change['old_uid']))
            connection.execute('UPDATE trip_appointments SET appointment_id=? WHERE appointment_id=?',(temp_uid,change['old_uid']))
            connection.execute('UPDATE road_visit_notes SET appointment_id=? WHERE appointment_id=?',(temp_uid,change['old_uid']))
            connection.execute('UPDATE road_visit_attachments SET appointment_id=? WHERE appointment_id=?',(temp_uid,change['old_uid']))
        for change in changes:
            connection.execute('UPDATE appointment_objectives SET appointment_id=?, visit_date=?, visit_time=?, updated_at=? WHERE appointment_id=?',(change['new_uid'],change['date'],change['time'],now,change['temp_uid']))
            connection.execute('UPDATE trip_appointments SET appointment_id=?, visit_date=?, visit_time=?, sequence_no=?, updated_at=? WHERE appointment_id=?',(change['new_uid'],change['date'],change['time'],change['sequence'],now,change['temp_uid']))
            connection.execute('UPDATE road_visit_notes SET appointment_id=?, visit_date=?, visit_time=?, updated_at=? WHERE appointment_id=?',(change['new_uid'],change['date'],change['time'],now,change['temp_uid']))
            connection.execute('UPDATE road_visit_attachments SET appointment_id=?, visit_date=?, visit_time=? WHERE appointment_id=?',(change['new_uid'],change['date'],change['time'],change['temp_uid']))
        connection.commit()

    audit_event('appointment_rescheduled',f'{store_name}: {old_date} {old_time} -> {new_date} {new_time} ({kind}); day re-optimised',trip_id=trip_id)
    overflow_count=len(overflow) if 'overflow' in locals() else 0
    if overflow_count:
        return True,(f'{store_name} moved to {target_day.strftime("%a %d %b")} at {_display_clock(target_minutes)}. '
                     f'The day was rebuilt within 8:00 am–5:00 pm and {overflow_count} call(s) were moved to Needs Rescheduling.')
    return True,f'{store_name} moved to {target_day.strftime("%a %d %b")} at {_display_clock(target_minutes)}. The full day was re-optimised within 8:00 am–5:00 pm.'


def _repair_legacy_route_planner_overnight_anchors(connection, schedule, customers):
    """Upgrade legacy Route Planner schedules whose multi-day anchors repeated the original endpoints.

    Older saved routes could store the same trip start on every day and the same trip finish on every
    day even when the user's intent was to continue overnight.  New schedules carry explicit route-mode
    metadata.  For unmarked legacy Route Planner schedules, only repair the unmistakable pattern:
    every day starts at the same point, every day finishes at the same different point.  A genuine
    return-to-start trip has finish == start and is deliberately left alone.
    """
    if not schedule or not str(schedule['filename'] or '').startswith('Route Planner -'):
        return schedule
    raw=str(schedule['raw_html'] or '')
    soup=BeautifulSoup(raw,'html.parser')
    body=soup.body or soup
    if body.get('data-route-planner') or body.get('data-overnight-mode') is not None or body.get('data-return-to-start') is not None:
        return schedule
    day_divs=[]
    for div in soup.select('div.scheduleday'):
        class_date=next((c for c in div.get('class',[]) if c.startswith('scheduleday_') and c!='scheduleday'),'')
        try:
            d=datetime.strptime(class_date.replace('scheduleday_',''),'%Y%m%d').date()
        except ValueError:
            continue
        day_divs.append((d,div))
    day_divs.sort(key=lambda x:x[0])
    if len(day_divs)<2:
        return schedule

    def point(div,prefix):
        try:
            return (float(div.get(f'data-{prefix}-lat')),float(div.get(f'data-{prefix}-lng')))
        except (TypeError,ValueError):
            return None
    def same_point(a,b,tol=0.001):
        return bool(a and b and abs(a[0]-b[0])<=tol and abs(a[1]-b[1])<=tol)

    starts=[point(div,'start') for _,div in day_divs]
    finishes=[point(div,'finish') for _,div in day_divs]
    if not starts[0] or not finishes[0]:
        return schedule
    repeated_start=all(same_point(starts[0],x) for x in starts[1:])
    repeated_finish=all(same_point(finishes[0],x) for x in finishes[1:])
    if not repeated_start or not repeated_finish or same_point(starts[0],finishes[0]):
        return schedule

    customer_lookup={str(k).casefold():v for k,v in customers.items()}
    repaired=False
    for idx,(_,div) in enumerate(day_divs):
        rows=div.select('tr.stop')
        if not rows:
            continue
        last_store=_schedule_store_from_row(rows[-1])
        last_customer=customer_lookup.get(last_store.strip().casefold(),{})
        try:
            last_lat=float(last_customer.get('latitude')); last_lng=float(last_customer.get('longitude'))
        except (TypeError,ValueError):
            continue
        if idx < len(day_divs)-1:
            div['data-finish-lat']=str(last_lat)
            div['data-finish-lng']=str(last_lng)
            div['data-finish-label']=last_store or 'Previous day final call'
            repaired=True
        if idx+1 < len(day_divs):
            next_div=day_divs[idx+1][1]
            next_div['data-start-lat']=str(last_lat)
            next_div['data-start-lng']=str(last_lng)
            next_div['data-start-label']=last_store or 'Previous day final call'
            repaired=True

    if not repaired:
        return schedule
    body['data-route-planner']='1'
    body['data-overnight-mode']='1'
    body['data-return-to-start']='0'
    upgraded=str(soup)
    now=datetime.now().isoformat(timespec='seconds')
    connection.execute('UPDATE trip_schedules SET raw_html=?, uploaded_at=? WHERE id=?',(upgraded,now,schedule['id']))
    connection.commit()
    refreshed=connection.execute('SELECT * FROM trip_schedules WHERE id=?',(schedule['id'],)).fetchone()
    return refreshed or schedule


def _visit_email_clock(value):
    """Format a saved appointment time in the concise style used in visit heads-up emails."""
    minutes=_workspace_time_minutes(value)
    hour=(minutes//60)%24
    minute=minutes%60
    suffix='am' if hour<12 else 'pm'
    hour12=hour%12 or 12
    return f"{hour12}{('.%02d' % minute) if minute else ''}{suffix}"


def _visit_email_when(visit_date, visit_time):
    """Describe the visit naturally while keeping the actual scheduled time explicit in the next line."""
    try:
        today=nz_today()
    except Exception:
        today=date.today()
    minutes=_workspace_time_minutes(visit_time)
    daypart='morning' if minutes < 12*60 else ('afternoon' if minutes < 17*60 else 'evening')
    if visit_date == today:
        return f"this {daypart}"
    if visit_date == today + timedelta(days=1):
        return f"tomorrow {daypart}"
    return f"on {visit_date.strftime('%A')} {daypart}"


def _build_visit_notification_drafts(appointments, customers):
    """Create one editable heads-up email per scheduled customer visit.

    All contacts marked notify_before_visit for the same visit are grouped into one draft,
    matching Riverlea's one-email-per-store workflow rather than creating duplicate messages.
    """
    drafts=[]
    missing=[]
    recipient_count=0
    if not appointments:
        return drafts,missing,recipient_count

    with db_connect() as connection:
        connection.row_factory=sqlite3.Row
        contacts=[dict(r) for r in connection.execute(
            "SELECT * FROM customer_contacts WHERE COALESCE(notify_before_visit,0)=1 ORDER BY contact_name COLLATE NOCASE"
        ).fetchall()]

    by_customer_id={}
    by_store={}
    for contact in contacts:
        cid=int(contact.get('customer_id') or 0)
        if cid:
            by_customer_id.setdefault(cid,[]).append(contact)
        store=str(contact.get('store_name') or '').strip().casefold()
        if store:
            by_store.setdefault(store,[]).append(contact)

    seen=set()
    for appt in sorted(appointments,key=lambda x:(x.get('date') or date.min,_workspace_time_minutes(x.get('time')))):
        store=str(appt.get('store') or '').strip()
        if not store or not appt.get('date'):
            continue
        customer=customers.get(store.casefold(),{}) or {}
        cid=int(appt.get('customer_id') or customer.get('id') or 0)
        flagged=list(by_customer_id.get(cid,[])) if cid else []
        if not flagged:
            flagged=list(by_store.get(store.casefold(),[]))
        if not flagged:
            continue
        key=(appt['date'].isoformat(),str(appt.get('time') or ''),cid or store.casefold())
        if key in seen:
            continue
        seen.add(key)

        usable=[]
        no_email=[]
        seen_email=set()
        for contact in flagged:
            email=str(contact.get('email') or '').strip()
            if not email:
                no_email.append(str(contact.get('contact_name') or 'Unnamed contact').strip())
                continue
            email_key=email.casefold()
            if email_key in seen_email:
                continue
            seen_email.add(email_key)
            usable.append(contact)
        if no_email:
            missing.append(f"{store}: {', '.join(no_email)} marked for visit notification but has no email address")
        if not usable:
            continue

        names=[str(c.get('contact_name') or '').strip() for c in usable if str(c.get('contact_name') or '').strip()]
        greeting_name=(names[0].split()[0] if len(usable)==1 and names else 'team')
        try:
            now_local=datetime.now(NZ_TIMEZONE)
        except Exception:
            now_local=datetime.now()
        greeting_part='morning' if now_local.hour < 12 else 'afternoon'
        opening_line='Trust you had a great weekend!' if now_local.weekday() in (0,1) else 'Trust you are having a great week!'
        visit_when=_visit_email_when(appt['date'],appt.get('time'))
        time_text=_visit_email_clock(appt.get('time'))
        raw_city=str(customer.get('city') or '').strip()
        location_name=raw_city.title() if raw_city else store
        subject=f"Riverlea Store Visit – {appt['date'].strftime('%A')} {appt['date'].day} {appt['date'].strftime('%B')}"
        body=(
            f"Good {greeting_part} {greeting_name},\n\n"
            f"{opening_line}\n\n"
            f"Just a heads up that I will be coming through to {location_name} {visit_when} and was hoping to call in for a visit.\n"
            f"I am aiming to arrive around {time_text}, and trust this fits in with your busy schedule?\n\n"
            "Many thanks,"
        )
        emails=[str(c.get('email') or '').strip() for c in usable]
        drafts.append({
            'store_name':store,
            'date_display':appt['date'].strftime('%A %d %B %Y'),
            'time_display':_display_clock(appt.get('time')),
            'to_display':'; '.join(emails),
            'subject':subject,
            'body':body,
            'recipient_count':len(emails),
        })
        recipient_count += len(emails)
    return drafts,missing,recipient_count


@app.route('/trips/<int:trip_id>/visit-email-draft.eml', methods=['POST'])
def trip_visit_email_eml(trip_id):
    """Create an Outlook-compatible unsent .eml file from an editable visit-notification draft."""
    if not _trip_accessible(trip_id):
        abort(404)

    # Keep header values single-line so edited text cannot create extra mail headers.
    to_value='; '.join(part.strip() for part in re.split(r'[;,]+', str(request.form.get('to') or '')) if part.strip())
    subject=' '.join(str(request.form.get('subject') or '').replace('\r',' ').replace('\n',' ').split()).strip()
    body=str(request.form.get('body') or '').replace('\r\n','\n').replace('\r','\n')
    store_name=' '.join(str(request.form.get('store_name') or 'Visit').replace('\r',' ').replace('\n',' ').split()).strip() or 'Visit'

    if not to_value:
        abort(400, description='A recipient email address is required.')
    if not subject:
        subject='Upcoming visit'

    from email.message import EmailMessage
    from email.policy import SMTP

    message=EmailMessage(policy=SMTP)
    # Outlook recognises X-Unsent: 1 as a compose/draft message rather than a sent email.
    message['X-Unsent']='1'
    message['To']=to_value.replace(';', ',')
    message['Subject']=subject
    message.set_content(body)

    payload=message.as_bytes()
    safe_store=re.sub(r'[^A-Za-z0-9._-]+','-',store_name).strip('-._')[:60] or 'visit'
    filename=f"{safe_store}-visit-draft.eml"
    response=send_file(
        BytesIO(payload),
        mimetype='message/rfc822',
        as_attachment=True,
        download_name=filename,
        max_age=0,
    )
    response.headers['Cache-Control']='no-store, max-age=0'
    return response


def build_trip_workspace(trip_id, calendar_month=None):
    import calendar as _calendar
    with db_connect() as connection:
        connection.row_factory=sqlite3.Row
        trip=_trip_row_for_current_user(connection, trip_id)
        if not trip:
            return None
        schedule=connection.execute('SELECT * FROM trip_schedules WHERE trip_plan_id=? ORDER BY id DESC LIMIT 1',(trip_id,)).fetchone()
        customers={r['name'].strip().casefold():dict(r) for r in connection.execute('SELECT * FROM route_customers').fetchall()}
        action_owner_user_id = _private_workspace_user_id()
        if action_owner_user_id is not None:
            action_rows = connection.execute(
                "SELECT MIN(store_name) AS store_name, COUNT(*) AS n FROM store_actions WHERE status!='Completed' AND owner_user_id=? GROUP BY lower(store_name)",
                (action_owner_user_id,),
            ).fetchall()
        else:
            action_rows = connection.execute("SELECT MIN(store_name) AS store_name, COUNT(*) AS n FROM store_actions WHERE status!='Completed' GROUP BY lower(store_name)").fetchall()
        actions={r['store_name'].strip().casefold():r['n'] for r in action_rows}
        if schedule:
            schedule=_repair_legacy_route_planner_overnight_anchors(connection,schedule,customers)
        notes={}
        notes_by_appointment={}
        notes_by_date_store={}
        objectives={}
        completed=0
        if schedule:
            for r in connection.execute('SELECT * FROM appointment_objectives WHERE schedule_id=?',(schedule['id'],)).fetchall(): objectives[r['appointment_id']]=dict(r)
            for r in connection.execute('SELECT * FROM road_visit_notes WHERE schedule_id=?',(schedule['id'],)).fetchall():
                record=dict(r)
                key=(r['visit_date'],r['visit_time'],r['store_name'].strip().casefold())
                notes[key]=record
                if record.get('appointment_id'):
                    notes_by_appointment[record['appointment_id']]=record
                notes_by_date_store.setdefault((r['visit_date'],r['store_name'].strip().casefold()),[]).append(record)
                if r['completed']: completed+=1
    trip=dict(trip)
    try:
        sd=datetime.strptime(trip['start_date'],'%Y-%m-%d').date(); ed=datetime.strptime(trip['end_date'],'%Y-%m-%d').date()
        trip['date_display']=sd.strftime('%d %b %Y') if sd==ed else f"{sd.strftime('%d %b')}–{ed.strftime('%d %b %Y')}"
    except Exception:
        sd=date.today(); ed=sd; trip['date_display']=f"{trip.get('start_date','')}–{trip.get('end_date','')}"
    appointments=parse_schedule_appointments(schedule['raw_html'],date.min,trip.get('start_date')) if schedule else []
    custom_schedule_events=[]
    if schedule:
        custom_soup=BeautifulSoup(schedule['raw_html'],'html.parser')
        for day_div in custom_soup.select('div.scheduleday'):
            class_date=next((c for c in day_div.get('class',[]) if c.startswith('scheduleday_') and c!='scheduleday'),'')
            try:
                custom_date=datetime.strptime(class_date.replace('scheduleday_',''),'%Y%m%d').date()
            except ValueError:
                continue
            for row in day_div.select('tr.custom-stop'):
                try:
                    duration=max(5,int(row.get('data-duration') or 60))
                except (TypeError,ValueError):
                    duration=60
                try:
                    lat=float(row.get('data-latitude')) if str(row.get('data-latitude') or '').strip() else None
                    lon=float(row.get('data-longitude')) if str(row.get('data-longitude') or '').strip() else None
                except (TypeError,ValueError):
                    lat=lon=None
                custom_schedule_events.append({'date':custom_date,'time':_schedule_time_from_row(row),'name':_schedule_store_from_row(row),'duration':duration,'custom_type':str(row.get('data-custom-type') or 'appointment'),'location':str(row.get('data-location-label') or '').strip(),'latitude':lat,'longitude':lon})

    # Calls intentionally pulled out by the optimiser because they cannot fit inside the
