@app.route('/admin/daily-home-content')
@admin_required
def daily_home_content_admin():
    with db_connect() as connection:
        joke_count = int(connection.execute("SELECT COUNT(*) FROM daily_home_jokes WHERE COALESCE(active,1)=1").fetchone()[0] or 0)
        word_count = int(connection.execute("SELECT COUNT(*) FROM daily_home_words WHERE COALESCE(active,1)=1").fetchone()[0] or 0)
    return render_template_string(
        PAGE, view='admin_daily_content', open_action_count=get_open_action_count(),
        daily_joke_count=joke_count, daily_word_count=word_count,
        success=request.args.get('success',''), error=request.args.get('error',''),
    )


@app.route('/admin/daily-home-content/upload/<kind>', methods=['POST'])
@admin_required
def daily_home_content_upload(kind):
    if kind not in {'jokes','words'}:
        abort(404)
    try:
        items = _parse_daily_content_upload(request.files.get('content_file'), kind)
        if not items:
            raise ValueError('No valid rows were found in that file.')
        now = nz_now_iso()
        added = 0
        with db_connect() as connection:
            if kind == 'jokes':
                existing = {str(r[0]).strip().casefold() for r in connection.execute("SELECT joke_text FROM daily_home_jokes").fetchall()}
                for item in items:
                    text_value = str(item.get('joke_text') or '').strip()
                    key = text_value.casefold()
                    if not text_value or key in existing:
                        continue
                    connection.execute("INSERT INTO daily_home_jokes(id,joke_text,active,created_at) VALUES (?,?,1,?)", (uuid.uuid4().hex,text_value,now))
                    existing.add(key); added += 1
            else:
                existing = {str(r[0]).strip().casefold() for r in connection.execute("SELECT word FROM daily_home_words").fetchall()}
                for item in items:
                    word = str(item.get('word') or '').strip(); definition = str(item.get('definition') or '').strip()
                    key = word.casefold()
                    if not word or not definition or key in existing:
                        continue
                    connection.execute("INSERT INTO daily_home_words(id,word,definition,example,active,created_at) VALUES (?,?,?,?,1,?)", (uuid.uuid4().hex,word,definition,str(item.get('example') or '').strip(),now))
                    existing.add(key); added += 1
            connection.commit()
        label = 'joke' if kind == 'jokes' else 'word'
        return redirect(url_for('daily_home_content_admin', success=f'Added {added} new {label}{"s" if added != 1 else ""}.'))
    except Exception as exc:
        return redirect(url_for('daily_home_content_admin', error=str(exc)))



